fn poll_until_dialog<F>(
    mut evaluation: Pin<&mut F>,
    controller: &JavaScriptDialogController,
    cx: &mut FutureContext<'_>,
) -> JavaScriptDialog
where
    F: Future<Output = JsResult<JsValue>>,
{
    for _ in 0..64 {
        if let Some(dialog) = controller.pending() {
            return dialog;
        }
        if let Poll::Ready(result) = evaluation.as_mut().poll(cx) {
            panic!("evaluation completed before opening a dialog: {result:?}");
        }
    }
    panic!("evaluation did not open a dialog within the poll budget");
}

fn poll_until_ready<F>(mut evaluation: Pin<&mut F>, cx: &mut FutureContext<'_>) -> JsResult<JsValue>
where
    F: Future<Output = JsResult<JsValue>>,
{
    for _ in 0..64 {
        if let Poll::Ready(result) = evaluation.as_mut().poll(cx) {
            return result;
        }
    }
    panic!("evaluation did not complete within the poll budget");
}

#[test]
fn alert_blocks_script_until_exactly_once_resolution() {
    let mut runtime = JsRuntime::new().unwrap();
    let controller = runtime.javascript_dialog_controller();
    let mut evaluation =
        Box::pin(runtime.eval_async(
            "globalThis.afterAlert = false; alert('Stop'); afterAlert = true; afterAlert",
        ));
    let waker: &'static Waker = Waker::noop();
    let mut cx = FutureContext::from_waker(waker);

    let dialog = poll_until_dialog(evaluation.as_mut(), &controller, &mut cx);
    assert_eq!(
        dialog,
        JavaScriptDialog {
            id: 1,
            kind: JavaScriptDialogKind::Alert,
            message: "Stop".to_string(),
            default_prompt: None,
        }
    );
    assert_eq!(
        controller.handle(dialog.id + 1, true, None),
        Err(JavaScriptDialogError::StaleDialog {
            expected: dialog.id,
            actual: dialog.id + 1,
        })
    );
    assert_eq!(controller.pending(), Some(dialog.clone()));

    boa_gc::force_collect();
    controller.handle(dialog.id, true, None).unwrap();
    assert_eq!(
        controller.handle(dialog.id, true, None),
        Err(JavaScriptDialogError::NoPendingDialog)
    );
    assert_eq!(
        poll_until_ready(evaluation.as_mut(), &mut cx)
            .unwrap()
            .as_boolean(),
        Some(true)
    );
}

#[test]
fn owned_page_task_preserves_fifo_order_across_a_dialog_suspension() {
    let runtime = JsRuntime::new().unwrap();
    let mut task = Box::pin(runtime.into_page_task(
        7,
        vec![
            PageTaskSource::Classic {
                source: "globalThis.pageTaskOrder = ['first']".to_string(),
                label: "first".to_string(),
                script_node_id: None,
            },
            PageTaskSource::Classic {
                source: "pageTaskOrder.push('before-dialog'); alert('Pause'); pageTaskOrder.push('after-dialog')".to_string(),
                label: "dialog".to_string(),
                script_node_id: None,
            },
            PageTaskSource::Classic {
                source: "pageTaskOrder.push('last')".to_string(),
                label: "last".to_string(),
                script_node_id: None,
            },
        ],
    ));
    let controller = task.dialog_controller();
    let waker: &'static std::task::Waker = std::task::Waker::noop();
    let mut context = FutureContext::from_waker(waker);
    let dialog = loop {
        assert!(matches!(task.as_mut().poll(&mut context), Poll::Pending));
        if let Some(dialog) = controller.pending() {
            break dialog;
        }
    };
    assert_eq!(dialog.message, "Pause");
    controller.handle(dialog.id, true, None).unwrap();
    let mut completed = loop {
        if let Poll::Ready(completed) = task.as_mut().poll(&mut context) {
            break completed;
        }
    };
    assert_eq!(completed.generation, 7);
    assert_eq!(completed.result, Ok(Vec::new()));
    assert_eq!(
        completed
            .runtime
            .eval("pageTaskOrder.join(',')")
            .unwrap()
            .as_string()
            .unwrap()
            .to_std_string_escaped(),
        "first,before-dialog,after-dialog,last"
    );
}

#[test]
fn owned_page_task_cancellation_recovers_runtime_without_running_continuation() {
    let runtime = JsRuntime::new().unwrap();
    let mut task = Box::pin(runtime.into_page_task(
        11,
        vec![PageTaskSource::Classic {
            source: "globalThis.beforeCancel = true; alert('Cancel'); globalThis.afterCancel = true"
                .to_string(),
            label: "cancelled".to_string(),
            script_node_id: None,
        }],
    ));
    let controller = task.dialog_controller();
    let waker: &'static std::task::Waker = std::task::Waker::noop();
    let mut context = FutureContext::from_waker(waker);
    while controller.pending().is_none() {
        assert!(matches!(task.as_mut().poll(&mut context), Poll::Pending));
    }
    task.cancel();
    let mut completed = match task.as_mut().poll(&mut context) {
        Poll::Ready(completed) => completed,
        Poll::Pending => panic!("cancelled page task did not return its runtime"),
    };
    assert_eq!(completed.generation, 11);
    assert_eq!(completed.result, Err(PageTaskError::Cancelled));
    assert_eq!(controller.pending(), None);
    assert_eq!(
        completed
            .runtime
            .eval("beforeCancel === true && typeof afterCancel === 'undefined'")
            .unwrap()
            .as_boolean(),
        Some(true)
    );
}

#[test]
fn owned_page_task_timeout_stops_script_and_recovers_runtime() {
    let sandbox = SandboxConfig {
        timeout: Duration::from_millis(2),
        max_loop_iterations: u64::MAX,
    };
    let runtime =
        JsRuntime::with_document_and_sandbox(crate::dom::NodeHandle::document(), sandbox).unwrap();
    let mut task = Box::pin(runtime.into_page_task(
        19,
        vec![PageTaskSource::Classic {
            source: "for (;;) {}".to_string(),
            label: "timed out".to_string(),
            script_node_id: None,
        }],
    ));
    let waker: &'static Waker = Waker::noop();
    let mut context = FutureContext::from_waker(waker);
    let mut completed = loop {
        match task.as_mut().poll(&mut context) {
            Poll::Ready(completed) => break completed,
            Poll::Pending => {}
        }
    };
    assert_eq!(completed.generation, 19);
    assert_eq!(completed.result, Err(PageTaskError::TimedOut));
    assert_eq!(
        completed.runtime.eval("1 + 1").unwrap().as_number(),
        Some(2.0)
    );
}

