#[test]
fn xml_http_request_get_completes_and_abort_suppresses_completion() {
    let listener = bind_loopback().unwrap();
    let address = listener.local_addr().unwrap();
    let handle = FixtureWorker::spawn(move || {
        let mut stream = accept_with_timeout(&listener, ACCEPT_TIMEOUT).unwrap();
        let _ = read_request_headers(&mut stream, READ_TIMEOUT).unwrap();
        let response = b"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nhello";
        stream.write_all(response).unwrap();
    });

    let mut runtime = JsRuntime::new().unwrap();
    runtime.set_base_url(format!("http://{address}/").parse().unwrap());
    runtime
        .eval(&format!(
            r#"globalThis.xhrEvents = []; const xhr = new XMLHttpRequest(); xhr.onload = () => xhrEvents.push("load"); xhr.onloadend = () => xhrEvents.push("loadend"); xhr.open("GET", "http://127.0.0.1:{}/"); xhr.send(); globalThis.xhr = xhr;"#,
            address.port()
        ))
        .unwrap();
    runtime.run_until_idle().unwrap();
    handle.join();
    assert!(runtime
        .eval(r#"xhr.readyState === XMLHttpRequest.DONE && xhr.status === 200 && xhr.responseText === "hello" && xhrEvents.join(",") === "load,loadend""#)
        .unwrap()
        .as_boolean()
        .unwrap());

    let abort_listener = bind_loopback().unwrap();
    let abort_address = abort_listener.local_addr().unwrap();
    let abort_handle = FixtureWorker::spawn(move || {
        let mut stream = accept_with_timeout(&abort_listener, ACCEPT_TIMEOUT).unwrap();
        let _ = read_request_headers(&mut stream, READ_TIMEOUT).unwrap();
        let response = b"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nlater";
        stream.write_all(response).unwrap();
    });
    runtime
        .eval(&format!(
            r#"xhrEvents = []; xhr.open("GET", "http://127.0.0.1:{}/"); xhr.send(); xhr.abort();"#,
            abort_address.port()
        ))
        .unwrap();
    runtime.run_until_idle().unwrap();
    abort_handle.join();
    assert!(runtime
        .eval(r#"xhr.readyState === XMLHttpRequest.UNSENT && xhr.status === 0 && xhr.responseText === "" && xhrEvents.join(",") === "loadend""#)
        .unwrap()
        .as_boolean()
        .unwrap());
}

#[test]
fn xml_http_request_sends_request_and_exposes_states_and_response_headers() {
    let listener = bind_loopback().unwrap();
    let address = listener.local_addr().unwrap();
    let handle = FixtureWorker::spawn(move || {
        let mut stream = accept_with_timeout(&listener, ACCEPT_TIMEOUT).unwrap();
        let request = read_http_request(&mut stream);
        let request = String::from_utf8(request).unwrap();
        assert!(request.starts_with("PUT /api/item HTTP/1.1\r\n"));
        assert!(
            request
                .to_ascii_lowercase()
                .contains("x-requested-with: omoikane\r\n")
        );
        assert!(request.ends_with("\r\n\r\nupdated"));
        let body = b"accepted";
        write!(
            stream,
            "HTTP/1.1 202 Accepted\r\nX-Result: saved\r\nSet-Cookie: secret=value\r\nSet-Cookie2: legacy=hidden\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
            body.len()
        )
        .unwrap();
        stream.write_all(body).unwrap();
    });

    let mut runtime = JsRuntime::new().unwrap();
    runtime.set_base_url(format!("http://{address}/").parse().unwrap());
    runtime
        .eval(&format!(
            r#"globalThis.xhrStates = [];
                    const semanticXhr = new XMLHttpRequest();
                    semanticXhr.onreadystatechange = () => xhrStates.push(semanticXhr.readyState);
                    semanticXhr.open("PUT", "http://127.0.0.1:{}/api/item");
                    semanticXhr.setRequestHeader("X-Requested-With", "omoikane");
                    semanticXhr.send("updated");"#,
            address.port()
        ))
        .unwrap();
    runtime.run_until_idle().unwrap();
    handle.join();

    assert!(
        runtime
            .eval(&format!(
                r#"semanticXhr.status === 202 &&
                    semanticXhr.statusText === "Accepted" &&
                    semanticXhr.responseText === "accepted" &&
                    semanticXhr.responseURL === "http://127.0.0.1:{}/api/item" &&
                    semanticXhr.getResponseHeader("X-Result") === "saved" &&
                    semanticXhr.getResponseHeader("Set-Cookie") === null &&
                    semanticXhr.getResponseHeader("Set-Cookie2") === null &&
                    semanticXhr.getAllResponseHeaders().includes("x-result: saved\r\n") &&
                    !semanticXhr.getAllResponseHeaders().includes("set-cookie") &&
                    xhrStates.join(",") === "1,2,3,4""#,
                address.port()
            ))
            .unwrap()
            .as_boolean()
            .unwrap()
    );
}

#[test]
fn xml_http_request_reports_download_and_upload_progress_events() {
    let listener = bind_loopback().unwrap();
    let address = listener.local_addr().unwrap();
    let handle = FixtureWorker::spawn(move || {
        let mut stream = accept_with_timeout(&listener, ACCEPT_TIMEOUT).unwrap();
        let request = read_http_request(&mut stream);
        let request = String::from_utf8(request).unwrap();
        assert!(request.ends_with("\r\n\r\nrequest"));
        stream
            .write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nhello")
            .unwrap();
    });

    let mut runtime = JsRuntime::new().unwrap();
    runtime.set_base_url(format!("http://{address}/").parse().unwrap());
    runtime
        .eval(&format!(
            r#"globalThis.downloadEvents = [];
                globalThis.uploadEvents = [];
                globalThis.uploadObjectCalls = 0;
                const recordProgress = (target, label, type) => event =>
                  target.push([label, type, event.loaded, event.total,
                    event.lengthComputable, event instanceof ProgressEvent].join(":"));
                const xhr = new XMLHttpRequest();
                const uploadObject = {{ handleEvent(event) {{
                  if (event.type === "progress") uploadObjectCalls++;
                }}}};
                for (const type of ["loadstart", "progress", "load", "loadend"])
                  xhr.addEventListener(type, recordProgress(downloadEvents, "download", type));
                for (const type of ["loadstart", "progress", "load", "loadend"])
                  xhr.upload.addEventListener(type, recordProgress(uploadEvents, "upload", type));
                xhr.upload.addEventListener("progress", uploadObject);
                xhr.upload.addEventListener("progress", uploadObject);
                xhr.upload.addEventListener("progress", null);
                xhr.open("POST", "http://127.0.0.1:{}/upload");
                xhr.send("request");
                globalThis.progressXhr = xhr;"#,
            address.port()
        ))
        .unwrap();
    runtime.run_until_idle().unwrap();
    handle.join();

    assert!(runtime
        .eval(
            r#"downloadEvents.join("|") ===
                  "download:loadstart:0:0:false:true|download:progress:5:5:true:true|download:load:5:5:true:true|download:loadend:5:5:true:true" &&
                uploadEvents.join("|") ===
                  "upload:loadstart:0:7:true:true|upload:progress:7:7:true:true|upload:load:7:7:true:true|upload:loadend:7:7:true:true" &&
                progressXhr.upload instanceof XMLHttpRequestUpload &&
                progressXhr.upload instanceof EventTarget &&
                uploadObjectCalls === 1 &&
                progressXhr.status === 200 && progressXhr.responseText === "hello""#,
        )
        .unwrap()
        .as_boolean()
        .unwrap());
}

#[test]
fn xml_http_request_timeout_is_exclusive_and_finishes_with_loadend() {
    let listener = bind_loopback().unwrap();
    let address = listener.local_addr().unwrap();
    let handle = FixtureWorker::spawn(move || {
        let mut stream = accept_with_timeout(&listener, ACCEPT_TIMEOUT).unwrap();
        let _ = read_http_request(&mut stream);
        std::thread::sleep(std::time::Duration::from_millis(100));
        let _ = stream.write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 4\r\n\r\nlate");
    });

    let mut runtime = JsRuntime::new().unwrap();
    runtime.set_base_url(format!("http://{address}/").parse().unwrap());
    runtime
        .eval(&format!(
            r#"globalThis.timeoutEvents = [];
                const xhr = new XMLHttpRequest();
                for (const type of ["loadstart", "progress", "load", "error", "timeout", "loadend"])
                  xhr.addEventListener(type, event => timeoutEvents.push([
                    type, event.loaded, event.total, event instanceof ProgressEvent].join(":")));
                xhr.timeout = 10;
                xhr.open("GET", "http://127.0.0.1:{}/slow");
                xhr.send();
                globalThis.timeoutXhr = xhr;"#,
            address.port()
        ))
        .unwrap();
    runtime.run_until_idle().unwrap();
    handle.join();

    let state = runtime
        .eval(r#"JSON.stringify([timeoutEvents, timeoutXhr.readyState, timeoutXhr.status, timeoutXhr.responseText])"#)
        .unwrap();
    assert!(
        runtime
            .eval(
                r#"timeoutEvents.join("|") ===
                  "loadstart:0:0:true|timeout:0:0:true|loadend:0:0:true" &&
                timeoutXhr.readyState === XMLHttpRequest.DONE &&
                timeoutXhr.status === 0 && timeoutXhr.responseText === """#,
            )
            .unwrap()
            .as_boolean()
            .unwrap_or(false),
        "state={}",
        state.display()
    );
}

#[test]
fn xml_http_request_timeout_uses_unsigned_long_conversion() {
    let mut runtime = JsRuntime::new().unwrap();
    assert!(
        runtime
            .eval(
                r#"(() => {
                    const xhr = new XMLHttpRequest();
                    xhr.timeout = Infinity;
                    const infinity = xhr.timeout === 0;
                    xhr.timeout = -1;
                    const negative = xhr.timeout === 4294967295;
                    xhr.timeout = 2 ** 32;
                    const wrapped = xhr.timeout === 0;
                    xhr.timeout = 1.9;
                    return infinity && negative && wrapped && xhr.timeout === 1;
                })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
}

