#[test]
fn style_parser_preserves_quoted_and_unquoted_data_uri_semicolons() {
    let doc = NodeHandle::document();
    let unquoted = NodeHandle::element("div");
    let quoted = NodeHandle::element("div");
    unquoted.set_attribute("id", "unquoted");
    quoted.set_attribute("id", "quoted");
    doc.append_child(unquoted.clone());
    doc.append_child(quoted.clone());

    let mut runtime = JsRuntime::with_document(doc).unwrap();
    runtime
        .eval(
            r#"
                const unquoted = document.getElementById("unquoted");
                const quoted = document.getElementById("quoted");
                unquoted.setAttribute(
                    "style",
                    "background-image: url(data:image/png;base64,AAAA); color: red;"
                );
                quoted.setAttribute(
                    "style",
                    'background-image: url("data:image/svg+xml;utf8,<svg></svg>"); color: blue;'
                );
                // Force a read-modify-write cycle; both data URLs must survive
                // when the declaration list is serialized again.
                unquoted.style.marginTop = "1px";
                quoted.style.marginTop = "2px";
                "#,
        )
        .unwrap();

    assert_eq!(
        eval_str(&mut runtime, "unquoted.style.backgroundImage"),
        "url(data:image/png;base64,AAAA)"
    );
    assert_eq!(eval_str(&mut runtime, "unquoted.style.color"), "red");
    assert_eq!(
        eval_str(&mut runtime, "quoted.style.backgroundImage"),
        r#"url("data:image/svg+xml;utf8,<svg></svg>")"#
    );
    assert_eq!(eval_str(&mut runtime, "quoted.style.color"), "blue");
    assert!(unquoted.attributes().unwrap()["style"].contains("data:image/png;base64,AAAA"));
    assert!(quoted.attributes().unwrap()["style"].contains("data:image/svg+xml;utf8,<svg></svg>"));
}

#[test]
fn style_set_property_kebab_and_camel_are_consistent() {
    // setProperty uses CSS (kebab-case) names; the value must be readable via
    // both the camelCase accessor and getPropertyValue, and vice versa.
    let doc = NodeHandle::document();
    let div = NodeHandle::element("div");
    doc.append_child(div.clone());

    let mut runtime = JsRuntime::with_document(doc).unwrap();
    runtime
        .eval(
            r#"
            const el = document.querySelector("div");
            el.style.setProperty("background-color", "blue");
            el.style.marginTop = "5px";
        "#,
        )
        .unwrap();

    // kebab set -> camelCase read and getPropertyValue read.
    assert_eq!(
        eval_str(
            &mut runtime,
            "document.querySelector('div').style.backgroundColor"
        ),
        "blue"
    );
    assert_eq!(
        eval_str(
            &mut runtime,
            "document.querySelector('div').style.getPropertyValue('background-color')"
        ),
        "blue"
    );
    // camelCase set -> kebab getPropertyValue read.
    assert_eq!(
        eval_str(
            &mut runtime,
            "document.querySelector('div').style.getPropertyValue('margin-top')"
        ),
        "5px"
    );
}

#[test]
fn style_color_properties_ignore_invalid_assignments() {
    let doc = NodeHandle::document();
    let div = NodeHandle::element("div");
    doc.append_child(div);
    let mut runtime = JsRuntime::with_document(doc).unwrap();

    runtime
        .eval(
            r##"
                const target = document.querySelector("div");
                target.style.color = "blue";
                target.style.color = "not-a-color";
                target.style.backgroundColor = "red";
                target.style.backgroundColor = "#12";
                target.style.setProperty("border-top-color", "green");
                target.style.setProperty("border-top-color", "rgb(1, 2)");
                target.style.outlineColor = "purple";
                target.style.outlineColor = "red, green";
                const sheetNode = document.createElement("style");
                sheetNode.textContent = "div { color: green; }";
                document.appendChild(sheetNode);
                const rule = sheetNode.sheet.cssRules[0];
                rule.style.color = "not-a-color";
                globalThis.ruleColor = rule.style.color;
                "##,
        )
        .unwrap();

    assert_eq!(
        eval_str(
            &mut runtime,
            "JSON.stringify([target.style.color, target.style.backgroundColor, target.style.borderTopColor, target.style.outlineColor])",
        ),
        r#"["blue","red","green","purple"]"#,
    );
    assert_eq!(
        eval_str(&mut runtime, "getComputedStyle(target).color"),
        "rgb(0, 0, 255)",
    );
    assert_eq!(eval_str(&mut runtime, "ruleColor"), "green");
    assert!(
        !runtime
            .eval("CSS.supports('color', 'not-a-color')")
            .unwrap()
            .as_boolean()
            .unwrap()
    );
    assert!(
        runtime
            .eval("CSS.supports('color', 'currentcolor')")
            .unwrap()
            .as_boolean()
            .unwrap()
    );
}

#[test]
fn content_visibility_cssom_rejects_invalid_values_and_serializes_intrinsic_size() {
    let doc = NodeHandle::document();
    let div = NodeHandle::element("div");
    doc.append_child(div);
    let mut runtime = JsRuntime::with_document(doc).unwrap();

    let result = eval_str(
        &mut runtime,
        r#"(() => {
                const target = document.querySelector("div");
                target.style.contentVisibility = "visible auto";
                const invalidVisibility = target.style.contentVisibility;
                target.style.contentVisibility = "hidden";
                target.style.containIntrinsicWidth = "1px auto";
                const invalidWidth = target.style.containIntrinsicWidth;
                target.style.containIntrinsicSize = "5px 5px";
                const equalAxes = target.style.containIntrinsicSize;
                target.style.containIntrinsicSize = "auto 1px auto 1px";
                const equalAutoAxes = target.style.containIntrinsicSize;
                target.style.containIntrinsicSize = "2em 3px";
                return [invalidVisibility, target.style.contentVisibility,
                        invalidWidth, equalAxes, equalAutoAxes,
                        target.style.containIntrinsicSize].join("|");
            })()"#,
    );

    assert_eq!(result, "|hidden||5px|auto 1px|2em 3px");
}

