#[test]
fn underline_cssom_validates_normalizes_inherits_and_serializes_calc() {
    let doc = crate::html::TreeBuilder::parse(
        "<div style='font-size:20px;text-underline-position:under left;text-underline-offset:20%'><span id='target' style='font-size:40px'></span></div>",
    ).document();
    let mut runtime = JsRuntime::with_document(doc).unwrap();
    runtime
        .eval("var target=document.getElementById('target')")
        .unwrap();
    assert_eq!(
        eval_str(
            &mut runtime,
            "JSON.stringify([getComputedStyle(target).textUnderlinePosition,getComputedStyle(target).textUnderlineOffset])"
        ),
        r#"["under left","20%"]"#
    );
    runtime.eval("target.style.textUnderlinePosition='right under';target.style.textUnderlinePosition='auto left';target.style.textUnderlineOffset='0';target.style.textUnderlineOffset='from-font'").unwrap();
    assert_eq!(
        eval_str(
            &mut runtime,
            "JSON.stringify([target.style.textUnderlinePosition,target.style.textUnderlineOffset])"
        ),
        r#"["under right","0px"]"#
    );
    runtime
        .eval("target.style.textUnderlineOffset='calc(2em - 50%)'")
        .unwrap();
    assert_eq!(
        eval_str(&mut runtime, "getComputedStyle(target).textUnderlineOffset"),
        "calc(-50% + 80px)"
    );
    runtime
        .eval("target.style.textUnderlineOffset='calc(200% - 0.5em)'")
        .unwrap();
    assert_eq!(
        eval_str(&mut runtime, "getComputedStyle(target).textUnderlineOffset"),
        "calc(200% - 20px)"
    );
}

#[test]
fn text_decoration_thickness_cssom_computes_and_rejects_invalid_values() {
    let doc = crate::html::TreeBuilder::parse(
        "<div id='parent' style='font-size:20px;color:rgb(1,2,3);\
             text-decoration-thickness:9px'>\
             <span id='target'></span><span id='initial'></span></div>",
    )
    .document();
    let mut runtime = JsRuntime::with_document(doc).unwrap();

    runtime
        .eval(
            r#"
                const target = document.getElementById("target");
                target.style.textDecorationThickness = "2em";
                target.style.textDecoration = "underline 2em red";
                target.style.textDecoration = "underline thin blue";
                target.style.textDecorationThickness = "invalid";
                "#,
        )
        .unwrap();

    assert_eq!(
        eval_str(
            &mut runtime,
            "JSON.stringify([target.style.textDecorationThickness,\
                 getComputedStyle(target).textDecorationLine,\
                 getComputedStyle(target).textDecorationStyle,\
                 getComputedStyle(target).textDecorationThickness,\
                 getComputedStyle(document.getElementById('initial')).textDecorationThickness,\
                 getComputedStyle(document.getElementById('initial')).textDecorationColor])",
        ),
        r#"["2em","underline","solid","40px","auto","rgb(1, 2, 3)"]"#,
    );
    assert!(
        runtime
            .eval("CSS.supports('text-decoration-thickness','calc(20% + 2px)')")
            .unwrap()
            .as_boolean()
            .unwrap()
    );
    assert!(
        !runtime
            .eval("CSS.supports('text-decoration-thickness','from font')")
            .unwrap()
            .as_boolean()
            .unwrap()
    );
}

#[test]
fn cssom_preserves_typed_length_percentage_math_and_rejects_invalid_types() {
    let doc = crate::html::TreeBuilder::parse("<div id='target'></div><img id='image'>").document();
    let mut runtime = JsRuntime::with_document(doc).unwrap();

    runtime
        .eval(
            r#"
                const target = document.getElementById('target');
                const image = document.getElementById('image');
                target.style.width = 'min(80px, 50%)';
                target.style.left = 'max(calc(10% + 5px), 20px)';
                target.style.textDecorationThickness = 'clamp(1px, 25%, 10px)';
                image.style.objectPosition =
                  'min(80px, 50%) max(calc(10% + 5px), 20px)';
                "#,
        )
        .unwrap();

    assert_eq!(
        eval_str(
            &mut runtime,
            r#"JSON.stringify([
                  target.style.width,
                  target.style.left,
                  target.style.textDecorationThickness,
                  image.style.objectPosition,
                  getComputedStyle(target).width,
                  getComputedStyle(target).left,
                  getComputedStyle(target).textDecorationThickness,
                  getComputedStyle(image).objectPosition
                ])"#,
        ),
        r#"["min(80px, 50%)","max(calc(10% + 5px), 20px)","clamp(1px, 25%, 10px)","min(80px, 50%) max(calc(10% + 5px), 20px)","80px","max(10% + 5px, 20px)","clamp(1px, 25%, 10px)","min(80px, 50%) max(10% + 5px, 20px)"]"#,
    );
    assert!(
        runtime
            .eval(
                "CSS.supports('width','min(80px,50%)') && \
                     CSS.supports('left','max(10%,20px)') && \
                     CSS.supports('text-decoration-thickness','clamp(1px,25%,10px)') && \
                     !CSS.supports('width','min(1,2px)')",
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );

    runtime
        .eval("target.style.width='31px';target.style.width='min(1,2px)'")
        .unwrap();
    assert_eq!(eval_str(&mut runtime, "target.style.width"), "31px");

    runtime
        .eval(
            "target.style.cssText = \
                 'width:31px;width:min(1,2px);left:7px;left:max(1,2px)'",
        )
        .unwrap();
    assert_eq!(
        eval_str(
            &mut runtime,
            "JSON.stringify([target.style.cssText,target.style.width,target.style.left])",
        ),
        r#"["width: 31px; left: 7px;","31px","7px"]"#
    );

    runtime
        .eval(
            "target.setAttribute('style', \
                 'width:42px;width:min(1,2px);left:9px;left:max(1,2px)')",
        )
        .unwrap();
    assert_eq!(
        eval_str(
            &mut runtime,
            "JSON.stringify([target.style.cssText,target.style.width,target.style.left])",
        ),
        r#"["width: 42px; left: 9px;","42px","9px"]"#
    );
}

#[test]
