#[test]
fn css_supports_rules_expose_conditions_and_nested_rules() {
    let doc = crate::html::TreeBuilder::parse(
        "<html><head><style>@supports (display: grid) { main { display: grid; } } @supports/* comment */(display: block) { section { display: block; } }</style></head><body><main></main></body></html>",
    )
    .document();
    let mut runtime = JsRuntime::with_document(doc).unwrap();
    assert!(
        runtime
            .eval(
                r#"(() => {
                    const rule = document.styleSheets[0].cssRules[0];
                    return rule instanceof CSSSupportsRule &&
                        rule.conditionText === "(display: grid)" &&
                        rule.matches === true &&
                        rule.cssRules.length === 1 &&
                        rule.cssRules[0].selectorText === "main" &&
                        document.styleSheets[0].cssRules[1] instanceof CSSSupportsRule &&
                        document.styleSheets[0].cssRules[1].matches === true;
                })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
}

#[test]
fn css_layer_rules_expose_names_imports_and_live_children() {
    let doc = crate::html::TreeBuilder::parse(
        "<html><head><style>@layer first, second; @import url(data:text/css,) layer(imported); @layer outer { @layer inner { #target { width: 41px; } } }</style></head><body><div id='target'></div></body></html>",
    )
    .document();
    let mut runtime = JsRuntime::with_document(doc).unwrap();
    assert!(
        runtime
            .eval(
                r#"(() => {
                        const sheet = document.styleSheets[0];
                        const statement = sheet.cssRules[0];
                        const imported = sheet.cssRules[1];
                        const outer = sheet.cssRules[2];
                        const inner = outer.cssRules[0];
                        inner.insertRule('#target { height: 43px; }', 1);
                        return statement instanceof CSSLayerStatementRule &&
                            Object.isFrozen(statement.nameList) &&
                            statement.nameList.join('.') === 'first.second' &&
                            imported instanceof CSSImportRule &&
                            imported.layerName === 'imported' &&
                            imported.href === 'data:text/css,' &&
                            outer instanceof CSSLayerBlockRule && outer.name === 'outer' &&
                            inner instanceof CSSLayerBlockRule && inner.name === 'inner' &&
                            inner.cssRules.length === 2 &&
                            getComputedStyle(document.getElementById('target')).width === '41px' &&
                            getComputedStyle(document.getElementById('target')).height === '43px';
                    })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
}

#[test]
fn imported_dynamic_style_dispatches_load_and_applies_its_layer() {
    let mut runtime =
        runtime_from_html("<html><head></head><body><div id='target'></div></body></html>");
    runtime
        .eval(
            r#"globalThis.__layerStyleLoads = 0;
                   const style = document.createElement('style');
                   style.textContent = '@import url("data:text/css,%23target%7Bwidth%3A47px%7D") layer(imported);';
                   style.addEventListener('load', () => { __layerStyleLoads++; });
                   document.head.appendChild(style);"#,
        )
        .unwrap();
    runtime.run_until_idle().unwrap();

    assert_eq!(eval_num(&mut runtime, "__layerStyleLoads"), 1.0);
    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('target')).width"
        ),
        "47px"
    );
}

#[test]
fn conditional_imports_share_rendering_and_cssom_state() {
    let doc = crate::html::TreeBuilder::parse(
        r#"<html><head><style>
                @import url("data:text/css,%23target%7Bwidth%3A47px%7D") layer(imported) supports(display: grid) screen and (min-width: 1px);
                @import url("data:text/css,%23target%7Bheight%3A99px%7D") layer(blocked) supports(unknown-property: value);
            </style></head><body><div id="target"></div></body></html>"#,
    )
    .document();
    let mut runtime = JsRuntime::with_document(doc).unwrap();

    assert!(
        runtime
            .eval(
                r#"(() => {
                        const target = document.getElementById('target');
                        const style = getComputedStyle(target);
                        const valid = document.styleSheets[0].cssRules[0];
                        const blocked = document.styleSheets[0].cssRules[1];
                        const imported = valid.styleSheet;
                        return style.width === '47px' && style.height !== '99px' &&
                            valid instanceof CSSImportRule &&
                            valid.layerName === 'imported' &&
                            valid.supportsText === 'display: grid' &&
                            valid.media instanceof MediaList &&
                            valid.media.length === 1 &&
                            valid.media[0] === 'screen and (min-width: 1px)' &&
                            valid.cssText === '@import url("data:text/css,%23target%7Bwidth%3A47px%7D") layer(imported) supports(display: grid) screen and (min-width: 1px);' &&
                            imported instanceof CSSStyleSheet &&
                            imported === valid.styleSheet &&
                            imported.href === valid.href &&
                            imported.cssRules.length === 1 &&
                            imported.cssRules[0].selectorText === '#target' &&
                            blocked.supportsText === 'unknown-property: value' &&
                            blocked.styleSheet === null;
                    })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
    assert!(
        runtime
            .eval(
                r#"(() => {
                        const sheet = new CSSStyleSheet();
                        sheet.replaceSync(
                            '@import url("bad.css") supports();' +
                            '@import url("media.css") layer(A, B, C);'
                        );
                        return sheet.cssRules.length === 1 &&
                            sheet.cssRules[0] instanceof CSSImportRule &&
                            sheet.cssRules[0].layerName === null &&
                            sheet.cssRules[0].media.mediaText === 'layer(A, B, C)';
                    })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
}

#[test]
fn css_scope_rules_expose_boundaries_and_nested_rules() {
    let doc = crate::html::TreeBuilder::parse(
        "<html><head><style>@scope { p { color: black; } } @scope (.card) to (.stop) { p { color: red; } } @scope/* comment */(.commented) { span { color: blue; } } @scope to(.limit) { em { color: green; } }</style></head><body></body></html>",
    )
    .document();
    let mut runtime = JsRuntime::with_document(doc).unwrap();
    assert!(
        runtime
            .eval(
                r#"(() => {
                    const implicit = document.styleSheets[0].cssRules[0];
                    const bounded = document.styleSheets[0].cssRules[1];
                    const commented = document.styleSheets[0].cssRules[2];
                    const limitOnly = document.styleSheets[0].cssRules[3];
                    return implicit instanceof CSSScopeRule &&
                        implicit instanceof CSSGroupingRule &&
                        !(implicit instanceof CSSConditionRule) &&
                        implicit.start === null && implicit.end === null &&
                        bounded instanceof CSSScopeRule &&
                        bounded.start === ".card" && bounded.end === ".stop" &&
                        bounded.cssRules.length === 1 &&
                        bounded.cssRules[0].selectorText === "p" &&
                        commented instanceof CSSScopeRule &&
                        commented.start === ".commented" &&
                        limitOnly.start === null && limitOnly.end === ".limit";
                })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
}

#[test]
fn css_scope_grouping_rule_mutations_recompute_cascade() {
    let doc = crate::html::TreeBuilder::parse(
        "<html><head><style>@scope (.card) { p { color: red; } }</style></head><body><section class='card'><p id='target'></p></section></body></html>",
    )
    .document();
    let mut runtime = JsRuntime::with_document(doc).unwrap();
    assert!(
        runtime
            .eval(
                r#"(() => {
                    const scope = document.styleSheets[0].cssRules[0];
                    scope.insertRule('#target { width: 33px; }', scope.cssRules.length);
                    return getComputedStyle(document.getElementById('target')).width === '33px' &&
                        scope.cssRules.length === 2;
                })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
    assert_eq!(
        eval_str(
            &mut runtime,
            "document.styleSheets[0].cssRules[0].cssRules[1].selectorText",
        ),
        "#target"
    );
    assert!(
        runtime
            .eval(
                r#"(() => {
                    const scope = document.styleSheets[0].cssRules[0];
                    scope.cssRules[1].selectorText = '#target';
                    scope.deleteRule(0);
                    return scope.cssRules.length === 1 &&
                        getComputedStyle(document.getElementById('target')).width === '33px';
                })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
    assert!(
        runtime
            .eval(
                r#"(() => {
                    try {
                        document.styleSheets[0].insertRule('@scope (.broken) trailing { p {} }', 0);
                        return false;
                    } catch (error) {
                        return error instanceof DOMException && error.name === 'SyntaxError';
                    }
                })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
}

#[test]
fn css_scope_recomputes_after_detach_reattach_and_respects_shadow_boundary() {
    let doc = crate::html::TreeBuilder::parse(
        "<html><head><style>p { color: black; }</style></head><body></body></html>",
    )
    .document();
    let mut runtime = JsRuntime::with_document(doc).unwrap();
    assert!(
        runtime
            .eval(
                r#"(() => {
                    const card = document.createElement('section');
                    const scopedStyle = document.createElement('style');
                    scopedStyle.textContent = '@scope { p { color: red; } }';
                    const paragraph = document.createElement('p');
                    card.appendChild(scopedStyle);
                    card.appendChild(paragraph);
                    document.body.appendChild(card);
                    globalThis.__scopeParagraph = paragraph;
                    globalThis.__scopeCard = card;
                    return getComputedStyle(paragraph).color === 'rgb(255, 0, 0)';
                })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
    assert!(
        runtime
            .eval(
                r#"(() => {
                    __scopeCard.remove();
                    const detached = getComputedStyle(__scopeParagraph).color;
                    document.body.appendChild(__scopeCard);
                    return detached !== 'rgb(255, 0, 0)' &&
                        getComputedStyle(__scopeParagraph).color === 'rgb(255, 0, 0)';
                })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
    assert!(runtime
        .eval(
            r#"(() => {
                    const host = document.createElement('x-scoped');
                    document.body.appendChild(host);
                    const shadow = host.attachShadow({ mode: 'open' });
                    shadow.innerHTML = '<style>@scope { p { color: blue; } }</style><p id="shadow-target"></p>';
                    const target = shadow.querySelector('#shadow-target');
                    return getComputedStyle(target).color === 'rgb(0, 0, 255)' &&
                        getComputedStyle(__scopeParagraph).color === 'rgb(255, 0, 0)';
                })()"#,
        )
        .unwrap()
        .as_boolean()
        .unwrap());
}

#[test]
fn css_container_rules_expose_name_query_and_nested_rules() {
    let doc = crate::html::TreeBuilder::parse(
        "<html><head><style>@container card (width >= 400px) { main { width: 20px; } } @container/* c */(inline-size > 10px) { p { color: red; } }</style></head><body></body></html>",
    )
    .document();
    let mut runtime = JsRuntime::with_document(doc).unwrap();
    assert!(
        runtime
            .eval(
                r#"(() => {
                    const named = document.styleSheets[0].cssRules[0];
                    const unnamed = document.styleSheets[0].cssRules[1];
                    return named instanceof CSSContainerRule &&
                        named instanceof CSSConditionRule &&
                        named.containerName === "card" &&
                        named.containerQuery === "(width >= 400px)" &&
                        named.conditionText === "card (width >= 400px)" &&
                        named.cssRules.length === 1 &&
                        named.cssRules[0].selectorText === "main" &&
                        unnamed instanceof CSSContainerRule &&
                        unnamed.containerName === "" &&
                        unnamed.containerQuery === "(inline-size > 10px)";
                })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
}

#[test]
fn size_container_query_controls_javascript_computed_style() {
    let doc = crate::html::TreeBuilder::parse(
        r#"<html><head><style>
                #shell { width: 500px; container-type: inline-size; container-name: shell; }
                #item { width: 10px; }
                @container shell (inline-size >= 400px) { #item { width: 75px; } }
            </style></head><body><section id="shell"><article id="item"></article></section></body></html>"#,
    )
    .document();
    let mut runtime = JsRuntime::with_document(doc).unwrap();
    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('item')).width"
        ),
        "75px"
    );
    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('shell')).containerType"
        ),
        "inline-size"
    );
    assert_eq!(
        eval_str(
            &mut runtime,
            "(() => { document.getElementById('shell').style.width = '300px'; return getComputedStyle(document.getElementById('item')).width; })()"
        ),
        "10px",
        "a forced layout after container geometry changes must re-evaluate the query"
    );
}

