#[test]
fn matches_and_closest() {
    let doc = NodeHandle::document();
    let html = NodeHandle::element("html");
    let body = NodeHandle::element("body");
    let div = NodeHandle::element("div");
    div.set_attribute("class", "wrapper");
    let span = NodeHandle::element("span");
    doc.append_child(html.clone());
    html.append_child(body.clone());
    body.append_child(div.clone());
    div.append_child(span.clone());

    let mut runtime = JsRuntime::with_document(doc).unwrap();
    let matches = runtime
        .eval("document.querySelector('span').matches('span')")
        .unwrap()
        .as_boolean()
        .unwrap();
    assert!(matches, "span should match 'span'");

    let closest = runtime
        .eval("document.querySelector('span').closest('.wrapper').tagName")
        .unwrap()
        .as_string()
        .unwrap()
        .to_std_string_escaped();
    assert_eq!(closest, "DIV");

    assert!(runtime
        .eval("(() => { try { document.querySelector('span').matches(); } catch (error) { return error instanceof TypeError; } return false; })()")
        .unwrap()
        .as_boolean()
        .unwrap());
    assert!(runtime
        .eval("(() => { try { document.querySelector('span').matches(''); } catch (error) { return error instanceof DOMException && error.name === 'SyntaxError'; } return false; })()")
        .unwrap()
        .as_boolean()
        .unwrap());
}

#[test]
fn storage_methods_follow_webidl_string_conversion_and_ordering() {
    let doc = NodeHandle::document();
    let mut runtime = JsRuntime::with_document(doc).unwrap();
    assert!(
        runtime
            .eval(
                r#"(() => {
                    localStorage.clear();
                    localStorage.setItem(1, null);
                    localStorage.setItem(undefined, 42);
                    localStorage.setItem("last", "value");
                    const ordered = localStorage.length === 3 &&
                        localStorage.key(0) === "1" &&
                        localStorage.key(1) === "undefined" &&
                        localStorage.key(2) === "last" &&
                        localStorage.key(3) === null &&
                        localStorage.getItem(1) === "null" &&
                        localStorage.getItem() === "42";
                    localStorage.setItem("1", "updated");
                    const stable = localStorage.key(0) === "1";
                    localStorage.removeItem(1);
                    const removed = localStorage.getItem("1") === null &&
                        localStorage.key(0) === "undefined";
                    localStorage.clear();
                    return ordered && stable && removed && localStorage.length === 0;
                })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
}

#[test]
fn indexeddb_open_upgrade_transaction_and_clone_isolation() {
    let mut runtime =
        JsRuntime::with_document_and_url(default_document(), "https://indexeddb.example.test/")
            .unwrap();
    runtime
        .eval(
            r#"globalThis.idbProbe = { events: [], value: null, count: -1, error: '' };
                   const open = indexedDB.open('books', 1);
                   open.onupgradeneeded = event => {
                     idbProbe.events.push('upgrade:' + event.oldVersion + '>' + event.newVersion);
                     event.target.result.createObjectStore('books', { keyPath: 'id', autoIncrement: true });
                   };
                   open.onerror = event => { idbProbe.error = event.target.error.name; };
                   open.onsuccess = event => {
                     idbProbe.events.push('open');
                     const db = event.target.result;
                     const tx = db.transaction('books', 'readwrite');
                     tx.oncomplete = () => idbProbe.events.push('complete');
                     const store = tx.objectStore('books');
                     const original = { title: 'first', nested: { value: 3 } };
                     store.add(original).onsuccess = event => {
                       original.title = 'mutated';
                       idbProbe.events.push('add:' + event.target.result);
                     };
                     store.get(1).onsuccess = event => {
                       idbProbe.value = event.target.result.title + ':' + event.target.result.nested.value;
                     };
                     store.count().onsuccess = event => { idbProbe.count = event.target.result; };
                   };"#,
        )
        .unwrap();
    assert_eq!(
        runtime.eval("idbProbe.events.length").unwrap().as_number(),
        Some(0.0)
    );
    runtime.run_until_idle().unwrap();
    assert_eq!(
        eval_str(&mut runtime, "idbProbe.events.join('|')"),
        "upgrade:0>1|open|add:1|complete",
    );
    assert_eq!(eval_str(&mut runtime, "idbProbe.value"), "first:3");
    assert_eq!(eval_str(&mut runtime, "String(idbProbe.count)"), "1");
    assert_eq!(eval_str(&mut runtime, "idbProbe.error"), "");
    runtime
        .eval(
            r#"globalThis.idbSecond = { value: '', names: '', rejected: '' };
                   const reopen = indexedDB.open('books');
                   reopen.onsuccess = event => {
                     const db = event.target.result;
                     idbSecond.names = Array.from(db.objectStoreNames).join(',');
                     const request = db.transaction('books').objectStore('books').get(1);
                     request.onsuccess = event => { idbSecond.value = event.target.result.title; };
                   };
                   indexedDB.open('books', 0).onerror = event => { idbSecond.rejected = event.target.error.name; };"#,
        )
        .unwrap();
    runtime.run_until_idle().unwrap();
    assert_eq!(
        eval_str(
            &mut runtime,
            "idbSecond.value + '|' + idbSecond.names + '|' + idbSecond.rejected"
        ),
        "first|books|TypeError"
    );
}

#[test]
fn indexeddb_rejects_array_key_paths_and_normalizes_boxed_store_names() {
    let mut runtime = JsRuntime::with_document_and_url(
        default_document(),
        "https://indexeddb-keypath.example.test/",
    )
    .unwrap();
    runtime
        .eval(
            r#"globalThis.idbEdge = { objectStore: '', index: '', boxed: '' };
                   const request = indexedDB.open('edge', 1);
                   request.onupgradeneeded = event => {
                     const db = event.target.result;
                     try { db.createObjectStore('bad', { keyPath: ['a', 'b'] }); }
                     catch (error) { idbEdge.objectStore = error.name; }
                     const store = db.createObjectStore('books');
                     try { store.createIndex('bad', ['a', 'b']); }
                     catch (error) { idbEdge.index = error.name; }
                   };
                   request.onsuccess = event => {
                     try { event.target.result.transaction(new String('books')); idbEdge.boxed = 'ok'; }
                     catch (error) { idbEdge.boxed = error.name; }
                   };"#,
        )
        .unwrap();
    runtime.run_until_idle().unwrap();
    assert_eq!(
        eval_str(
            &mut runtime,
            "idbEdge.objectStore + '|' + idbEdge.index + '|' + idbEdge.boxed"
        ),
        "NotSupportedError|NotSupportedError|ok",
    );
}

fn serve_visit_documents(first_body: &str) -> (u16, FixtureWorker<Vec<String>>) {
    serve_visit_documents_with_timeout(first_body, ACCEPT_TIMEOUT)
}

fn serve_visit_documents_with_timeout(
    first_body: &str,
    timeout: Duration,
) -> (u16, FixtureWorker<Vec<String>>) {
    let listener = bind_loopback().unwrap();
    let port = listener.local_addr().unwrap().port();
    let first_body = first_body.to_owned();
    let (ready_tx, ready_rx) = std::sync::mpsc::channel();
    let server = FixtureWorker::spawn(move || {
        let mut paths = Vec::new();
        ready_tx.send(()).unwrap();
        for expected_path in ["/first", "/second"] {
            // Runtime setup and handling the previous document must not consume
            // the next request's accept budget.
            let mut stream = accept_with_timeout(&listener, timeout).unwrap_or_else(|error| {
                panic!(
                    "visit fixture waiting for {expected_path} (accept timeout {timeout:?}, received {paths:?}): {error}"
                )
            });
            let request = read_request_headers(&mut stream, READ_TIMEOUT).unwrap_or_else(|error| {
                panic!(
                    "visit fixture reading {expected_path} headers (received {paths:?}): {error}"
                )
            });
            let path = request.split_whitespace().nth(1).unwrap().to_owned();
            let body = if path == "/first" {
                first_body.as_str()
            } else {
                "<html><body>second</body></html>"
            };
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                body.len(),
                body
            );
            stream.write_all(response.as_bytes()).unwrap();
            paths.push(path);
        }
        paths
    });
    ready_rx.recv_timeout(ACCEPT_TIMEOUT).unwrap();
    (port, server)
}

#[test]
fn visit_fixture_request_processing_does_not_consume_the_next_accept_timeout() {
    let timeout = Duration::from_millis(500);
    let (port, server) = serve_visit_documents_with_timeout("first", timeout);
    let mut first = TcpStream::connect(("127.0.0.1", port)).unwrap();
    first.set_read_timeout(Some(READ_TIMEOUT)).unwrap();
    first
        .write_all(b"GET /first HTTP/1.1\r\nHost: localhost\r\n")
        .unwrap();
    // Keep the first request in progress beyond the old shared deadline.
    std::thread::sleep(timeout * 2);
    first.write_all(b"\r\n").unwrap();
    let mut response = String::new();
    first.read_to_string(&mut response).unwrap();
    assert!(response.ends_with("first"));

    let mut second = TcpStream::connect(("127.0.0.1", port))
        .expect("visit fixture must still accept the second request after processing the first");
    second.set_read_timeout(Some(READ_TIMEOUT)).unwrap();
    second
        .write_all(b"GET /second HTTP/1.1\r\nHost: localhost\r\n\r\n")
        .unwrap();
    response.clear();
    second.read_to_string(&mut response).unwrap();
    assert!(response.ends_with("<html><body>second</body></html>"));
    assert_eq!(
        server.join(),
        vec!["/first".to_string(), "/second".to_string()]
    );
}

#[test]
fn iframe_visits_use_the_navigating_frame_origin_and_top_level_site() {
    let (port, server) = serve_visit_documents(
        "<html><body><script>setTimeout(() => location.assign('/second'), 0)</script></body></html>",
    );
    let top_url = format!("http://localhost:{port}/top");
    let first = format!("http://127.0.0.1:{port}/first");
    let second = format!("http://127.0.0.1:{port}/second");
    let storage = StorageManager::new();
    let session = storage.create_session();
    let mut runtime = JsRuntime::with_document_url_and_storage(
        default_document(),
        &top_url,
        storage.clone(),
        session,
    )
    .unwrap();
    let owner_source =
        VisitSource::new(StorageOrigin::from_url(&top_url).unwrap(), &top_url).unwrap();
    let child_source =
        VisitSource::new(StorageOrigin::from_url(&first).unwrap(), &top_url).unwrap();
    assert!(!storage.has_visited_url(&first, &owner_source));
    runtime
        .eval(&format!(
            "const frame = document.createElement('iframe'); frame.src = {first:?}; document.body.appendChild(frame)"
        ))
        .unwrap();
    runtime.run_until_idle().unwrap();
    runtime.tick(0).unwrap();
    runtime.run_until_idle().unwrap();

    assert_eq!(
        server.join(),
        vec!["/first".to_string(), "/second".to_string()]
    );
    assert!(storage.has_visited_url(&first, &owner_source));
    assert!(!storage.has_visited_url(&first, &child_source));
    assert!(storage.has_visited_url(&second, &child_source));
    assert!(!storage.has_visited_url(&second, &owner_source));
}

