#[test]
fn nested_about_blank_iframe_inherits_its_owning_documents_opaque_origin() {
    let document = crate::html::TreeBuilder::parse(
        "<html><body><iframe id='outer' src='data:text/html,%3Chtml%3E%3Cbody%3E%3C/body%3E%3C/html%3E'></iframe></body></html>",
    ).document();
    let mut runtime = JsRuntime::with_document_and_url(document, "https://example.com/").unwrap();

    assert!(
        runtime
            .eval(
                r#"(() => {
                      const outer = document.querySelector('#outer');
                      if (outer.contentDocument !== null) return false;
                      try { outer.contentWindow.document; return false; }
                      catch (error) { return error.name === 'SecurityError'; }
                    })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap(),
        "the tuple-origin parent must not reach the opaque data: Document"
    );

    // Build the nested about:blank from the host side because the top
    // Document is intentionally barred from the opaque outer Document.
    // Its inherited security-origin token must exactly match its creator's
    // opaque token, while neither Document gains a storage tuple.
    let (outer_document, outer_origin) = {
        let state = runtime.host_state.borrow();
        let outer = state.document.query_selector("#outer").unwrap();
        let outer_document = state.iframe_documents[&outer.identity()].document.clone();
        let origin = state.document_security_origins[&outer_document.identity()].clone();
        (outer_document, origin)
    };
    let nested = NodeHandle::element("iframe");
    outer_document
        .query_selector("body")
        .unwrap()
        .append_child(nested.clone());
    {
        let mut state = runtime.host_state.borrow_mut();
        state.register_tree(&nested);
        state.schedule_connected_resource_loads(&nested, true);
    }
    runtime.run_until_idle().unwrap();

    let state = runtime.host_state.borrow();
    let nested_document = &state.iframe_documents[&nested.identity()].document;
    assert_eq!(
        state.document_security_origins[&nested_document.identity()],
        outer_origin
    );
    assert_eq!(
        state.document_origins.get(&outer_document.identity()),
        Some(&None)
    );
    assert_eq!(
        state.document_origins.get(&nested_document.identity()),
        Some(&None)
    );
}

#[test]
fn performance_now_is_monotonic_and_has_epoch_time_origin() {
    let mut runtime = JsRuntime::with_document(default_document()).unwrap();
    assert!(
        runtime
            .eval(
                "(() => { const first = performance.now(); const second = performance.now(); \
                 return Number.isFinite(performance.timeOrigin) && performance.timeOrigin > 0 && \
                 first >= 0 && second >= first && \
                 Math.abs(Date.now() - (performance.timeOrigin + second)) < 1000 && \
                 Object.getOwnPropertyDescriptor(performance, 'timeOrigin').writable === false && \
                 (() => { const origin = performance.timeOrigin; performance.timeOrigin = 0; \
                   return performance.timeOrigin === origin; })(); })()"
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
}

#[test]
fn performance_navigation_and_resource_timing_entries_have_lifecycle_semantics() {
    let mut runtime =
        JsRuntime::with_document_and_url(default_document(), "https://example.test/index.html")
            .unwrap();
    assert!(runtime
        .eval(
            r#"(() => {
                  const navigation = performance.getEntriesByType("navigation");
                  if (navigation.length !== 1) return false;
                  const entry = navigation[0];
                  if (!(entry instanceof PerformanceNavigationTiming) ||
                      entry.name !== "https://example.test/index.html" ||
                      entry.entryType !== "navigation" || entry.startTime !== 0 ||
                      entry.duration < 0 || entry.type !== "navigate" ||
                      entry.redirectCount !== 0 || entry.toJSON().entryType !== "navigation" ||
                      entry.toJSON().type !== "navigate" ||
                      "navigationStart" in entry || "navigationStart" in entry.toJSON()) return false;
                  performance.clearResourceTimings();
                  performance.setResourceTimingBufferSize(2);
                  performance.mark("survivor");
                  const first = new Image();
                  first.src = "data:image/png;base64,AA==";
                  const second = new Image();
                  second.src = "data:image/png;base64,AA==";
                  const third = new Image();
                  third.src = "data:image/png;base64,AA==";
                  const resources = performance.getEntriesByType("resource");
                  const resourceStart = Object.getOwnPropertyDescriptor(first, "__resourceTimingStart");
                  const resourceRecorded = Object.getOwnPropertyDescriptor(first, "__resourceTimingRecorded");
                  return resources.length === 2 &&
                    resourceStart && resourceRecorded &&
                    resourceStart.enumerable === false && resourceRecorded.enumerable === false &&
                    resources.every(resource => resource instanceof PerformanceResourceTiming &&
                      resource.initiatorType === "img" && resource.responseEnd >= resource.startTime &&
                      resource.toJSON().initiatorType === "img") &&
                    performance.getEntriesByName("data:image/png;base64,AA==").length === 2;
                })()"#,
        )
        .unwrap()
        .as_boolean()
        .unwrap());
    assert!(
        runtime
            .eval(
                r#"(() => {
                  performance.clearResourceTimings();
                  return performance.getEntriesByType("resource").length === 0 &&
                    performance.getEntriesByType("navigation").length === 1 &&
                    performance.getEntriesByName("survivor", "mark").length === 1;
                })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
    runtime.fire_dom_content_loaded().unwrap();
    runtime.fire_load().unwrap();
    assert!(
        runtime
            .eval(
                r#"(() => {
                  const entry = performance.getEntriesByType("navigation")[0];
                  return entry.domInteractive >= 0 &&
                    entry.domContentLoadedEventStart <= entry.domContentLoadedEventEnd &&
                    entry.domContentLoadedEventEnd <= entry.domComplete &&
                    entry.loadEventStart <= entry.loadEventEnd;
                })()"#,
            )
            .unwrap()
            .as_boolean()
            .unwrap()
    );
}

