#[test]
fn get_computed_style_exposes_z_index_like_selector_test() {
    // Reproduces the shape of Acid3's selectorTest: a universal rule sets a
    // baseline z-index and a specific rule raises it. getComputedStyle must
    // report the numeric value (never "auto").
    let html = r#"<html><head><style>
            * { z-index: 0; position: absolute; }
            #target { z-index: 3; }
        </style></head><body><div id="target"></div><div id="other"></div></body></html>"#;
    let mut runtime = runtime_from_html(html);

    assert_eq!(
        eval_str(
            &mut runtime,
            "document.defaultView.getComputedStyle(document.getElementById('target'), '').zIndex"
        ),
        "3"
    );
    assert_eq!(
        eval_str(
            &mut runtime,
            "document.defaultView.getComputedStyle(document.getElementById('other'), '').zIndex"
        ),
        "0"
    );
}

#[test]
fn get_computed_style_inline_style_overrides_cascade() {
    let html = r#"<html><head><style>
            #target { color: red; }
        </style></head><body><div id="target" style="color: blue"></div></body></html>"#;
    let mut runtime = runtime_from_html(html);

    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('target'), '').color"
        ),
        "rgb(0, 0, 255)",
        "inline style must win over the cascaded stylesheet rule"
    );
}

#[test]
fn get_computed_style_is_shared_across_default_view_window_and_global() {
    let html = r#"<html><head><style>
            #target { white-space: pre-wrap; }
        </style></head><body><p id="target">hi</p></body></html>"#;
    let mut runtime = runtime_from_html(html);

    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle === window.getComputedStyle && \
                 window.getComputedStyle === document.defaultView.getComputedStyle"
        ),
        "true",
        "global / window / defaultView getComputedStyle must be the same function"
    );
    // And all three produce the same value.
    assert_eq!(
        eval_str(
            &mut runtime,
            "[getComputedStyle, window.getComputedStyle, document.defaultView.getComputedStyle]\
                 .map(f => f(document.getElementById('target'), '').whiteSpace).join(',')"
        ),
        "pre-wrap,pre-wrap,pre-wrap"
    );
}

#[test]
fn get_computed_style_recomputes_last_child_after_removal() {
    // Acid3 test 0 core: removing the final child makes the previous element
    // the new `:last-child`, which must recompute to `pre-wrap`.
    let html = r#"<html><head><style>
            #keep:last-child { white-space: pre-wrap; }
        </style></head><body><div id="parent"><p id="keep">a</p><p id="last">b</p></div></body></html>"#;
    let mut runtime = runtime_from_html(html);

    // Before removal `#keep` is not the last child, so no pre-wrap.
    assert_ne!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('keep'), '').whiteSpace"
        ),
        "pre-wrap"
    );

    // Remove the last element; forced reflow must observe the new structure.
    runtime
        .eval("(function(){ var l = document.getElementById('last'); l.parentNode.removeChild(l); })()")
        .unwrap();

    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('keep'), '').whiteSpace"
        ),
        "pre-wrap",
        "`:last-child` must re-match after the final child is removed"
    );
}

#[test]
fn get_computed_style_object_stays_live_after_style_mutations() {
    let html = r#"<html><head><style>
            #target { width: 10px; height: 11px; }
        </style></head><body><div id="target"></div></body></html>"#;
    let mut runtime = runtime_from_html(html);

    let result = eval_str(
        &mut runtime,
        r#"(() => {
                const target = document.getElementById("target");
                const style = getComputedStyle(target);
                const before = [style.width, style.height];
                const beforeLength = style.length;

                target.style.width = "20px";
                target.style.setProperty("--live-token", "ready");
                const names = [...style];
                const tokenIndex = names.indexOf("--live-token");
                const afterInline = [
                    style.width,
                    style.getPropertyValue("width"),
                    style.getPropertyValue("--live-token"),
                    style.length === beforeLength + 1,
                    style.item(tokenIndex),
                    style[tokenIndex],
                    "--live-token" in style,
                    style.cssText.includes("--live-token: ready;"),
                ];

                document.styleSheets[0].cssRules[0].style.height = "22px";
                const afterRule = style.height;
                const writeAccepted = Reflect.set(style, "height", "99px");
                return JSON.stringify({
                    before,
                    afterInline,
                    afterRule,
                    afterWrite: style.height,
                    writeAccepted,
                });
            })()"#,
    );

    assert_eq!(
        result,
        r#"{"before":["10px","11px"],"afterInline":["20px","20px","ready",true,"--live-token","--live-token",true,true],"afterRule":"22px","afterWrite":"22px","writeAccepted":false}"#,
        "a retained computed-style declaration must expose every later style mutation"
    );
}

#[test]
fn get_computed_style_resolves_layout_used_width_and_height() {
    let html = r#"<html><head><style>
            * { margin: 0; }
            #content-parent { width: 120px; }
            #content {
                width: auto;
                height: auto;
                padding: 5px 7px;
                border: 2px solid black;
                transform: scale(2);
            }
            #content > div { width: 80px; height: 30px; }
            #border-parent { width: 150px; }
            #border {
                box-sizing: border-box;
                width: auto;
                height: auto;
                padding: 5px 7px;
                border: 2px solid black;
            }
            #border > div { height: 30px; }
            #intrinsic-parent { width: 200px; }
            #intrinsic {
                width: min-content;
                padding: 0 7px;
                border: 2px solid black;
            }
            #intrinsic > span { display: inline-block; }
            #intrinsic > span:first-child { width: 50px; }
            #intrinsic > span:last-child { width: 70px; }
            #inline { display: inline; width: min-content; height: auto; }
            #gone { display: none; width: min-content; height: auto; }
        </style></head><body>
            <div id="content-parent"><div id="content"><div id="content-child"></div></div></div>
            <div id="border-parent"><div id="border"><div></div></div></div>
            <div id="intrinsic-parent"><div id="intrinsic"><span></span><span></span></div></div>
            <span id="inline">text</span>
            <div id="gone"></div>
        </body></html>"#;
    let mut runtime = runtime_from_html(html);

    let result = eval_str(
        &mut runtime,
        r#"(() => {
                const content = document.getElementById("content");
                const parent = document.getElementById("content-parent");
                const child = document.getElementById("content-child");
                const live = getComputedStyle(content);
                const before = [live.width, live.height];
                const rectWidth = content.getBoundingClientRect().width;
                parent.style.width = "130px";
                child.style.height = "40px";
                const after = [live.width, live.height];
                const border = getComputedStyle(document.getElementById("border"));
                const intrinsicElement = document.getElementById("intrinsic");
                const intrinsic = getComputedStyle(intrinsicElement);
                const inline = getComputedStyle(document.getElementById("inline"));
                const gone = getComputedStyle(document.getElementById("gone"));
                return JSON.stringify({
                    before,
                    rectWidth,
                    after,
                    border: [border.width, border.height],
                    intrinsic: [intrinsic.width, intrinsicElement.getBoundingClientRect().width],
                    inline: [inline.width, inline.height],
                    gone: [gone.width, gone.height],
                });
            })()"#,
    );

    assert_eq!(
        result,
        r#"{"before":["102px","30px"],"rectWidth":240,"after":["112px","40px"],"border":["150px","44px"],"intrinsic":["70px",88],"inline":["min-content","auto"],"gone":["min-content","auto"]}"#,
    );
}

#[test]
fn get_computed_style_uses_replaced_shadow_and_iframe_layout_sizes() {
    let html = r#"<html><head><style>
            * { margin: 0; }
            #image {
                box-sizing: border-box;
                width: auto;
                height: auto;
                padding: 10px;
                border: 5px solid black;
            }
            #host { width: 90px; }
            iframe { width: 120px; height: 80px; }
        </style></head><body>
            <img id="image" src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAAEElEQVR4AQEFAPr/AP8AAP8FAAH/+lyI0QAAAABJRU5ErkJggg==">
            <div id="host"></div>
            <iframe id="frame"></iframe>
        </body></html>"#;
    let mut runtime = runtime_from_html(html);

    let result = eval_str(
        &mut runtime,
        r#"(() => {
                const imageStyle = getComputedStyle(document.getElementById("image"));

                const host = document.getElementById("host");
                const root = host.attachShadow({ mode: "open" });
                const shadowTarget = document.createElement("div");
                shadowTarget.style.cssText = "width: auto; height: auto";
                const shadowChild = document.createElement("div");
                shadowChild.style.height = "17px";
                shadowTarget.appendChild(shadowChild);
                root.appendChild(shadowTarget);
                const shadowStyle = getComputedStyle(shadowTarget);

                const sub = document.getElementById("frame").contentDocument;
                const subStyle = sub.createElement("style");
                subStyle.textContent = "* { margin: 0 } #target { width: auto; height: auto; padding: 3px; border: 2px solid black } #child { height: 20px }";
                sub.head.appendChild(subStyle);
                const target = sub.createElement("div");
                target.id = "target";
                const child = sub.createElement("div");
                child.id = "child";
                target.appendChild(child);
                sub.body.appendChild(target);
                const liveSubStyle = getComputedStyle(target);
                const subBefore = [liveSubStyle.width, liveSubStyle.height];
                child.style.height = "25px";
                const subAfter = [liveSubStyle.width, liveSubStyle.height];

                return JSON.stringify({
                    image: [imageStyle.width, imageStyle.height],
                    shadow: [shadowStyle.width, shadowStyle.height],
                    subBefore,
                    subAfter,
                });
            })()"#,
    );

    assert_eq!(
        result,
        r#"{"image":["31px","31px"],"shadow":["90px","17px"],"subBefore":["110px","20px"],"subAfter":["110px","25px"]}"#,
    );
}

#[test]
fn constructable_stylesheets_apply_to_documents_and_shadow_roots() {
    let html = r#"<html><body><div id="target"></div><div id="host"></div></body></html>"#;
    let mut runtime = runtime_from_html(html);
    let result = eval_str(
        &mut runtime,
        r#"(() => {
                const sheet = new CSSStyleSheet();
                sheet.replaceSync('#target { width: 37px; }');
                document.adoptedStyleSheets = [sheet];
                const host = document.getElementById('host');
                const root = host.attachShadow({ mode: 'open' });
                const detachedHost = document.createElement('div');
                const detachedRoot = detachedHost.attachShadow({ mode: 'open' });
                const detachedSheet = new CSSStyleSheet();
                detachedSheet.replaceSync('.detached { height: 27px; }');
                detachedRoot.adoptedStyleSheets = [detachedSheet];
                const detached = document.createElement('span');
                detached.className = 'detached';
                detachedRoot.appendChild(detached);
                document.body.appendChild(detachedHost);
                const detachedHeight = getComputedStyle(detached).height;
                const shadowSheet = new CSSStyleSheet();
                shadowSheet.replaceSync('.inside { height: 19px; }');
                root.adoptedStyleSheets = [shadowSheet];
                const shared = new CSSStyleSheet();
                shared.replaceSync('#target { width: 41px; } .inside { width: 29px; }');
                const oldDocumentList = document.adoptedStyleSheets;
                document.adoptedStyleSheets = [sheet, shared];
                root.adoptedStyleSheets = [shadowSheet, shared];
                const inside = document.createElement('span');
                inside.className = 'inside';
                root.appendChild(inside);
                const before = getComputedStyle(document.getElementById('target')).width;
                const shadowBefore = getComputedStyle(inside).height;
                const sharedDocument = getComputedStyle(document.getElementById('target')).width;
                const sharedShadow = getComputedStyle(inside).width;
                sheet.insertRule('#target { height: 23px; }');
                const after = getComputedStyle(document.getElementById('target')).height;
                document.adoptedStyleSheets[0] = shared;
                document.adoptedStyleSheets.length = 1;
                const listIdentity = oldDocumentList === document.adoptedStyleSheets;
                const reverseReturnsList = document.adoptedStyleSheets.reverse() === document.adoptedStyleSheets;
                let nonConstructedError = '';
                try {
                    document.adoptedStyleSheets.push(document.createElement('style').sheet);
                } catch (error) {
                    nonConstructedError = error.name;
                }
                return [sheet.ownerNode === null, document.adoptedStyleSheets[0] === sheet,
                    detachedHeight, before, shadowBefore, sharedDocument, sharedShadow, listIdentity, reverseReturnsList,
                    nonConstructedError, after, sheet.cssRules.length,
                    typeof sheet.replace === 'function'].join('|');
            })()"#,
    );
    assert_eq!(
        result,
        "true|false|27px|41px|19px|41px|29px|true|true|NotAllowedError|23px|2|true"
    );
    runtime.eval("document.adoptedStyleSheets = []").unwrap();
    let document_id = runtime.host_state.borrow().document.identity();
    assert!(
        runtime
            .host_state
            .borrow()
            .adopted_stylesheets
            .get(&document_id)
            .is_none()
    );
}

#[test]
fn csp_blocks_constructable_stylesheets() {
    let mut runtime = runtime_from_html("<html><body><div id=target></div></body></html>");
    runtime.install_csp_policy(&["style-src 'none'".to_string()]);
    runtime
        .eval(
            r#"const sheet = new CSSStyleSheet();
                   sheet.replaceSync('#target { color: red; }');
                   document.adoptedStyleSheets = [sheet];"#,
        )
        .unwrap();
    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('target')).color",
        ),
        "rgb(0, 0, 0)"
    );
    assert_eq!(
        eval_str(
            &mut runtime,
            "document.cspViolations.map(v => v.effectiveDirective + ':' + v.resourceType).join(',')",
        ),
        "style-src:style"
    );
}

#[test]
fn constructable_stylesheet_replace_promise_recalculates_style() {
    let html = r#"<html><body><div id="target"></div></body></html>"#;
    let mut runtime = runtime_from_html(html);
    runtime
        .eval(
            r#"globalThis.sheet = new CSSStyleSheet();
                   sheet.replaceSync('#target { width: 11px; }');
                   document.adoptedStyleSheets = [sheet];
                   globalThis.replaced = false;
                   sheet.replace('#target { width: 47px; }').then(() => { replaced = true; });"#,
        )
        .unwrap();
    runtime.run_jobs().unwrap();
    let result = eval_str(
        &mut runtime,
        "[replaced, getComputedStyle(document.getElementById('target')).width, sheet.cssRules.length].join('|')",
    );
    assert_eq!(result, "true|47px|1");
}

#[test]
fn document_write_marks_style_dirty_so_getcomputedstyle_recomputes() {
    // Regression (integration review): a getComputedStyle query caches the
    // style resolver and clears the dirty flag. A subsequent
    // `document.write` that adds a <style> must re-dirty that cache so the
    // next query observes the newly written rule instead of returning the
    // stale pre-write result.
    let html = r#"<html><head></head><body><p id="target">hi</p></body></html>"#;
    let mut runtime = runtime_from_html(html);

    // Prime the cache: no rule applies yet, so this is not pre-wrap. The
    // query computes and caches the resolver (dirty = false).
    assert_ne!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('target'), '').whiteSpace"
        ),
        "pre-wrap",
        "no white-space rule applies before the write"
    );

    // Write a <style> targeting #target. Outside script execution the
    // fragment appends to <body>; collect_stylesheet_nodes still picks it
    // up. This must mark the cached resolver dirty.
    runtime
        .eval("document.write('<style>#target { white-space: pre-wrap; }</style>')")
        .unwrap();

    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('target'), '').whiteSpace"
        ),
        "pre-wrap",
        "getComputedStyle after document.write must observe the newly written rule"
    );
}

#[test]
fn document_open_marks_style_dirty_so_getcomputedstyle_recomputes() {
    // Regression (integration review): document.open() empties the document,
    // removing the <style> that fed the cached resolver. Without marking the
    // style cache dirty, a getComputedStyle query that already primed the
    // cache would keep reporting the pre-open rule.
    let html = r#"<html><head><style>
            #target { white-space: pre-wrap; }
        </style></head><body><p id="target">hi</p></body></html>"#;
    let mut runtime = runtime_from_html(html);

    // Retain the element so it stays queryable after the tree is emptied,
    // then prime the cache (dirty = false).
    runtime
        .eval("globalThis.__t = document.getElementById('target');")
        .unwrap();
    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(globalThis.__t, '').whiteSpace"
        ),
        "pre-wrap",
        "the <style> rule applies before document.open()"
    );

    // Empty the document via document.open(); the <style> is now gone.
    runtime.eval("document.open();").unwrap();

    assert_ne!(
        eval_str(
            &mut runtime,
            "getComputedStyle(globalThis.__t, '').whiteSpace"
        ),
        "pre-wrap",
        "after document.open() the removed <style> must no longer apply"
    );
}

#[test]
fn get_computed_style_symbol_traps_expose_only_the_iterator() {
    // Regression (integration review): the `has` trap must guard symbols the
    // same way `get` does, so `Symbol.x in getComputedStyle(el)` neither
    // throws nor is run through the CSS-name mapping. CSSStyleDeclaration
    // exposes Symbol.iterator, while unrelated symbols remain absent.
    let html = r#"<html><body><div id="target"></div></body></html>"#;
    let mut runtime = runtime_from_html(html);

    assert_eq!(
        eval_str(
            &mut runtime,
            "Symbol.iterator in getComputedStyle(document.getElementById('target'), '')"
        ),
        "true",
        "Symbol.iterator must be exposed and must not throw"
    );
    assert_eq!(
        eval_str(
            &mut runtime,
            "typeof getComputedStyle(document.getElementById('target'), '')[Symbol.iterator]"
        ),
        "function"
    );
    assert_eq!(
        eval_str(
            &mut runtime,
            "Symbol.toStringTag in getComputedStyle(document.getElementById('target'), '')"
        ),
        "false",
        "Symbol.toStringTag must not be a member and must not throw"
    );
}

#[test]
fn get_computed_style_is_read_only() {
    // Regression (integration review): getComputedStyle returns a read-only
    // CSSStyleDeclaration. Assigning to a property must be ignored and must
    // never pollute the underlying declaration, so a later read still
    // reports the computed value.
    let html = r#"<html><head><style>
            #target { white-space: pre-wrap; }
        </style></head><body><p id="target">hi</p></body></html>"#;
    let mut runtime = runtime_from_html(html);

    let result = eval_str(
        &mut runtime,
        r#"(function() {
                var cs = getComputedStyle(document.getElementById('target'), '');
                // Overwriting a known computed property must be ignored.
                try { cs.whiteSpace = 'nowrap'; } catch (e) { /* strict-mode TypeError ok */ }
                // Writing an unknown property must not land on the underlying decl.
                try { cs.notARealProp = 'polluted'; } catch (e) {}
                return cs.whiteSpace + '|' + cs.notARealProp;
            })()"#,
    );

    assert_eq!(
        result, "pre-wrap|",
        "writes to a computed style must be ignored and leave the declaration unpolluted"
    );
}

#[test]
fn window_metrics_default_to_bootstrap_viewport() {
    // Without an explicit set_viewport the DOM bootstrap's 1280x720 defaults
    // apply and are visible to scripts unchanged.
    let mut runtime = runtime_from_html("<html><body></body></html>");
    assert_eq!(eval_num(&mut runtime, "window.innerWidth"), 1280.0);
    assert_eq!(eval_num(&mut runtime, "window.innerHeight"), 720.0);
    assert_eq!(eval_num(&mut runtime, "window.outerWidth"), 1280.0);
    assert_eq!(eval_num(&mut runtime, "window.outerHeight"), 720.0);
    assert_eq!(eval_num(&mut runtime, "screen.width"), 1280.0);
    assert_eq!(eval_num(&mut runtime, "screen.height"), 720.0);
    assert_eq!(eval_num(&mut runtime, "screen.availWidth"), 1280.0);
    assert_eq!(eval_num(&mut runtime, "screen.availHeight"), 720.0);
}

#[test]
fn set_viewport_syncs_window_and_screen_metrics() {
    // set_viewport must wire the render viewport into the script-visible
    // window metrics so `window.innerWidth`/`innerHeight` (and `screen.*`)
    // agree with the render viewport, and match the `vw`/`vh` units resolved
    // by getComputedStyle against the same viewport. Regression: the fixed
    // 1280x720 bootstrap defaults previously leaked through.
    let html = r#"<html><head><style>
            #target { width: 100vw; height: 100vh; }
        </style></head><body><div id="target"></div></body></html>"#;
    let mut runtime = runtime_from_html(html);
    runtime.set_viewport(800.0, 600.0);

    assert_eq!(eval_num(&mut runtime, "window.innerWidth"), 800.0);
    assert_eq!(eval_num(&mut runtime, "window.innerHeight"), 600.0);
    assert_eq!(eval_num(&mut runtime, "window.outerWidth"), 800.0);
    assert_eq!(eval_num(&mut runtime, "window.outerHeight"), 600.0);
    assert_eq!(eval_num(&mut runtime, "screen.width"), 800.0);
    assert_eq!(eval_num(&mut runtime, "screen.height"), 600.0);
    assert_eq!(eval_num(&mut runtime, "screen.availWidth"), 800.0);
    assert_eq!(eval_num(&mut runtime, "screen.availHeight"), 600.0);

    // getComputedStyle's `vw`/`vh` resolution must agree with window.inner*.
    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('target'), '').width"
        ),
        "800px",
        "100vw must resolve against the same viewport window.innerWidth reports"
    );
    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('target'), '').height"
        ),
        "600px",
        "100vh must resolve against the same viewport window.innerHeight reports"
    );
}

#[test]
fn set_viewport_clamps_non_finite_and_negative_dimensions() {
    // Regression (integration review): raw f64/f32 viewport dimensions were
    // stored unchecked and flowed into StyleResolver::set_viewport and
    // layout_tree. A NaN/+inf/negative value must clamp to 0 (a safe finite
    // dimension) without panicking, and the script-visible metrics must stay
    // consistent with the vw/vh resolution.
    let html = r#"<html><head><style>
            #target { width: 100vw; height: 100vh; }
        </style></head><body><div id="target"></div></body></html>"#;
    let mut runtime = runtime_from_html(html);

    // NaN width and +inf height both clamp to 0.
    runtime.set_viewport(f32::NAN, f32::INFINITY);
    assert_eq!(eval_num(&mut runtime, "window.innerWidth"), 0.0);
    assert_eq!(eval_num(&mut runtime, "window.innerHeight"), 0.0);
    assert_eq!(eval_num(&mut runtime, "screen.width"), 0.0);
    assert_eq!(eval_num(&mut runtime, "screen.height"), 0.0);
    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('target'), '').width"
        ),
        "0px",
        "100vw against a clamped-to-zero viewport resolves to 0px, not NaN"
    );
    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('target'), '').height"
        ),
        "0px",
        "100vh against a clamped-to-zero viewport resolves to 0px, not NaN"
    );

    // Negative dimensions clamp to 0 as well.
    runtime.set_viewport(-100.0, -50.0);
    assert_eq!(eval_num(&mut runtime, "window.innerWidth"), 0.0);
    assert_eq!(eval_num(&mut runtime, "window.innerHeight"), 0.0);

    // A subsequent valid viewport is unaffected by the clamp.
    runtime.set_viewport(640.0, 480.0);
    assert_eq!(eval_num(&mut runtime, "window.innerWidth"), 640.0);
    assert_eq!(eval_num(&mut runtime, "window.innerHeight"), 480.0);
    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('target'), '').width"
        ),
        "640px",
        "a valid viewport still resolves 100vw normally after a clamped one"
    );
}

#[test]
fn get_bounding_client_rect_returns_block_geometry() {
    let html = r#"<html><head><style>
            * { margin: 0; padding: 0; }
            #box { width: 100px; height: 50px; }
        </style></head><body><div id="box"></div></body></html>"#;
    let mut runtime = runtime_from_html(html);

    assert_eq!(
        eval_num(
            &mut runtime,
            "document.getElementById('box').getBoundingClientRect().width"
        ),
        100.0
    );
    assert_eq!(
        eval_num(
            &mut runtime,
            "document.getElementById('box').getBoundingClientRect().height"
        ),
        50.0
    );
    assert_eq!(
        eval_num(
            &mut runtime,
            "document.getElementById('box').getBoundingClientRect().left"
        ),
        0.0
    );
    assert_eq!(
        eval_num(
            &mut runtime,
            "document.getElementById('box').getBoundingClientRect().top"
        ),
        0.0
    );
    assert_eq!(
        eval_num(
            &mut runtime,
            "document.getElementById('box').getBoundingClientRect().right"
        ),
        100.0
    );
    assert_eq!(
        eval_num(
            &mut runtime,
            "document.getElementById('box').getBoundingClientRect().bottom"
        ),
        50.0
    );
    assert_eq!(
        eval_num(&mut runtime, "document.getElementById('box').offsetWidth"),
        100.0
    );
    assert_eq!(
        eval_num(&mut runtime, "document.getElementById('box').offsetHeight"),
        50.0
    );
    assert_eq!(
        eval_num(&mut runtime, "document.getElementById('box').offsetLeft"),
        0.0
    );
    assert_eq!(
        eval_num(&mut runtime, "document.getElementById('box').offsetTop"),
        0.0
    );
}

#[test]
fn offset_parent_tracks_positioned_ancestor_and_box_visibility() {
    let html = r#"<html><head><style>
            * { margin: 0; }
            #positioned { position: relative; width: 100px; height: 100px; }
            #child { width: 20px; height: 20px; }
            #fixed { position: fixed; width: 10px; height: 10px; }
            #hidden { display: none; }
        </style></head><body><div id="positioned"><div id="child"></div></div>
          <div id="fixed"></div><div id="hidden"><div id="hidden-child"></div></div></body></html>"#;
    let mut runtime = runtime_from_html(html);
    let actual = eval_str(
        &mut runtime,
        r#"(() => {
                const positioned = document.getElementById('positioned');
                const child = document.getElementById('child');
                const fixed = document.getElementById('fixed');
                const hiddenChild = document.getElementById('hidden-child');
                const detached = document.createElement('div');
                const shadowHost = document.createElement('div');
                shadowHost.style.position = 'relative';
                document.body.appendChild(shadowHost);
                const shadowRoot = shadowHost.attachShadow({ mode: 'open' });
                const slot = document.createElement('slot');
                shadowRoot.appendChild(slot);
                const slotted = document.createElement('div');
                shadowHost.appendChild(slotted);
                return [
                    child.offsetParent === positioned,
                    fixed.offsetParent === null,
                    hiddenChild.offsetParent === null,
                    detached.offsetParent === null,
                    slotted.offsetParent === shadowHost,
                    child.offsetTop === 0 && child.offsetLeft === 0
                ].join('|');
            })()"#,
    );
    assert_eq!(actual, "true|true|true|true|true|true");
}

#[test]
fn bounding_client_rect_includes_transforms_but_offset_size_does_not() {
    let html = r#"<html><head><style>
            * { margin: 0; padding: 0; }
            #box { width: 100px; height: 50px; transform-origin: 0 0;
                   transform: translateX(100px) rotate(90deg); }
        </style></head><body><div id="box"></div></body></html>"#;
    let mut runtime = runtime_from_html(html);
    let expression = r#"(() => {
            const box = document.getElementById('box');
            const rect = box.getBoundingClientRect();
            return [rect.left, rect.top, rect.width, rect.height,
                    box.offsetWidth, box.offsetHeight].join('|');
        })()"#;

    assert_eq!(eval_str(&mut runtime, expression), "50|0|50|100|100|50");
}

#[test]
fn bounding_client_rect_composes_ancestor_and_element_transforms() {
    let html = r#"<html><head><style>
            * { margin: 0; padding: 0; }
            #parent { width: 20px; height: 20px; transform: translateX(30px); }
            #child { width: 10px; height: 10px; transform: scale(2); }
        </style></head><body><div id="parent"><div id="child"></div></div></body></html>"#;
    let mut runtime = runtime_from_html(html);
    let expression = r#"(() => {
            const rect = document.getElementById('child').getBoundingClientRect();
            return [rect.left, rect.top, rect.width, rect.height].join('|');
        })()"#;

    // scale(2) around the child's center expands -5..15, then the parent
    // translation moves that bounding box to 25..45.
    assert_eq!(eval_str(&mut runtime, expression), "25|-5|20|20");
}

#[test]
fn bounding_client_rect_handles_3d_perspective_without_changing_offset_size() {
    let html = r#"<html><head><style>
            * { margin: 0; padding: 0; }
            #box { width: 100px; height: 50px; transform-origin: 50% 50%;
                   transform: perspective(500px) rotateY(30deg) translateZ(20px); }
        </style></head><body><div id="box"></div></body></html>"#;
    let mut runtime = runtime_from_html(html);
    let expression = r#"(() => {
            const box = document.getElementById('box');
            const rect = box.getBoundingClientRect();
            const computed = getComputedStyle(box).transform;
            return [rect.width, rect.height, box.offsetWidth, box.offsetHeight,
                    Number.isFinite(rect.left), computed.includes('perspective')].join('|');
        })()"#;

    let values = eval_str(&mut runtime, expression)
        .split('|')
        .map(str::to_string)
        .collect::<Vec<_>>();
    let width = values[0].parse::<f32>().unwrap();
    let height = values[1].parse::<f32>().unwrap();
    assert!(width > 70.0 && width < 110.0);
    assert!(height > 45.0 && height < 60.0);
    assert_eq!(values[2], "100");
    assert_eq!(values[3], "50");
    assert_eq!(values[4], "true");
    assert_eq!(values[5], "true");
}

#[test]
fn inline_style_is_the_source_for_computed_width_and_layout() {
    let html = r#"<html><head><style>
            * { margin: 0; padding: 0; }
            #box { width: 80px; }
        </style></head><body><div id="box" style="width: 100px"></div></body></html>"#;
    let mut runtime = runtime_from_html(html);

    assert_eq!(
        eval_num(&mut runtime, "document.getElementById('box').offsetWidth"),
        100.0
    );
    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('box')).width"
        ),
        "100px"
    );

    runtime
        .eval("document.getElementById('box').setAttribute('style', 'width: 250px');")
        .unwrap();
    assert_eq!(
        eval_num(&mut runtime, "document.getElementById('box').offsetWidth"),
        250.0
    );

    runtime
        .eval("document.getElementById('box').removeAttribute('style');")
        .unwrap();
    assert_eq!(
        eval_num(&mut runtime, "document.getElementById('box').offsetWidth"),
        80.0
    );
    assert_eq!(
        eval_str(
            &mut runtime,
            "getComputedStyle(document.getElementById('box')).width"
        ),
        "80px"
    );
}

