// ── iframe / contentDocument (sub-browsing contexts) ────────────────────

/// Owns a reusable fixture until its test ends, then stops and joins its worker.
struct HttpTestServer {
    stop: std::sync::Arc<std::sync::atomic::AtomicBool>,
    worker: Option<FixtureWorker<()>>,
}

impl Drop for HttpTestServer {
    fn drop(&mut self) {
        self.stop.store(true, std::sync::atomic::Ordering::Release);
        if let Some(worker) = self.worker.take() {
            drop(worker);
        }
    }
}

fn spawn_reusable_http_server(
    response: impl Fn(&str, u16) -> String + Send + 'static,
) -> (u16, HttpTestServer) {
    let listener = bind_loopback().unwrap();
    let port = listener.local_addr().unwrap().port();
    let stop = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let worker_stop = stop.clone();
    let worker = FixtureWorker::spawn(move || {
        while !worker_stop.load(std::sync::atomic::Ordering::Acquire) {
            let mut stream =
                match accept_with_timeout(&listener, std::time::Duration::from_millis(50)) {
                    Ok(stream) => stream,
                    Err(error) if error.kind() == std::io::ErrorKind::TimedOut => continue,
                    Err(error) => panic!("fixture accept failed: {error}"),
                };
            let request = read_request_headers(&mut stream, READ_TIMEOUT).unwrap();
            stream.set_write_timeout(Some(READ_TIMEOUT)).unwrap();
            let path = request.split_whitespace().nth(1).unwrap_or("/");
            // Some resource tests deliberately abort requests; retain that behavior.
            let _ = stream.write_all(response(path, port).as_bytes());
        }
    });
    (
        port,
        HttpTestServer {
            stop,
            worker: Some(worker),
        },
    )
}

/// Answers every request with the same response, allowing iframe reloads
/// while the owning test keeps its server guard alive.
fn spawn_static_http_server(
    content_type: &'static str,
    body: &'static str,
) -> (u16, HttpTestServer) {
    spawn_reusable_http_server(move |_, _| {
        format!(
            "HTTP/1.1 200 OK\r\nContent-Type: {}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
            content_type,
            body.len(),
            body
        )
    })
}

/// Static test server with per-path content. Route data is copied before
/// spawning so callers can use ordinary local slice literals.
fn spawn_path_http_server(routes: &[(&str, &str, &str)]) -> (u16, HttpTestServer) {
    let routes: Vec<_> = routes
        .iter()
        .map(|(path, content_type, body)| {
            (
                (*path).to_string(),
                (*content_type).to_string(),
                (*body).to_string(),
            )
        })
        .collect();
    spawn_reusable_http_server(move |path, _| {
        let (status, content_type, body) = routes
            .iter()
            .find(|(route, _, _)| route == path)
            .map(|(_, content_type, body)| ("200 OK", content_type.as_str(), body.as_str()))
            .unwrap_or(("404 Not Found", "text/plain", "not found"));
        format!(
            "HTTP/1.1 {status}\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        )
    })
}

/// Serves a same-origin XHTML outer frame whose script creates a nested
/// same-origin XHTML frame. The nested script writes through `parent` so
/// tests can distinguish the owning child Realm from the top-level Realm.
fn spawn_nested_xhtml_server() -> (u16, HttpTestServer) {
    spawn_reusable_http_server(|path, port| {
        let body = if path.ends_with("/outer.xhtml") {
            format!(
                "<html xmlns='http://www.w3.org/1999/xhtml'><body><script>var nested=document.createElement('iframe');nested.src='http://127.0.0.1:{port}/nested.xhtml';document.body.appendChild(nested);</script></body></html>"
            )
        } else {
            "<html xmlns='http://www.w3.org/1999/xhtml'><body><script>parent.document.documentElement.setAttribute('data-nested-parent','yes')</script></body></html>".to_string()
        };
        format!(
            "HTTP/1.1 200 OK\r\nContent-Type: application/xhtml+xml\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
            body.len(),
            body
        )
    })
}

/// Serves an XHTML frame below `/frames/` and its relative external
/// script. The top-level page base is `/index.html`, so using the wrong
/// Realm/document base would request `/relative.js` and fail.
fn spawn_relative_child_script_server() -> (u16, HttpTestServer) {
    spawn_reusable_http_server(|path, _| {
        let (content_type, body) = if path.ends_with("/frames/child.xhtml") {
            (
                "application/xhtml+xml",
                "<html xmlns='http://www.w3.org/1999/xhtml'><head></head><body><script>var s=document.createElement('script');s.src='relative.js';s.addEventListener('load',function(){document.documentElement.setAttribute('data-relative-load','yes')});document.head.appendChild(s)</script></body></html>".to_string(),
            )
        } else if path.ends_with("/frames/relative.js") {
            (
                "text/javascript",
                "document.documentElement.setAttribute('data-relative-script','yes')".to_string(),
            )
        } else {
            ("text/plain", String::new())
        };
        format!(
            "HTTP/1.1 200 OK\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        )
    })
}

fn spawn_redirect_script_server() -> (u16, HttpTestServer) {
    spawn_reusable_http_server(|path, _| {
        let (status, headers, body) = match path {
            "/redirect.js" => ("302 Found", "Location: /final.js\r\n", ""),
            "/final.js" => (
                "200 OK",
                "Content-Type: text/javascript\r\n",
                "globalThis.redirectScriptRan = true;",
            ),
            _ => ("404 Not Found", "", ""),
        };
        format!(
            "HTTP/1.1 {status}\r\n{headers}Content-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len(),
        )
    })
}

#[test]
fn reusable_http_fixture_serves_reloads_and_joins_on_drop() {
    struct WorkerLifetime(std::sync::mpsc::Sender<()>);
    impl Drop for WorkerLifetime {
        fn drop(&mut self) {
            self.0.send(()).unwrap();
        }
    }
    let (finished, completion) = std::sync::mpsc::channel();
    let lifetime = WorkerLifetime(finished);
    let (port, server) = spawn_reusable_http_server(move |path, _| {
        let _ = &lifetime;
        assert_eq!(path, "/reload");
        "HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: close\r\n\r\nok".to_string()
    });
    for _ in 0..2 {
        let mut stream = TcpStream::connect(("127.0.0.1", port)).unwrap();
        stream.set_read_timeout(Some(READ_TIMEOUT)).unwrap();
        stream
            .write_all(b"GET /reload HTTP/1.1\r\nHost: local")
            .unwrap();
        stream.write_all(b"host\r\n\r\n").unwrap();
        let mut response = String::new();
        stream.read_to_string(&mut response).unwrap();
        assert!(response.ends_with("\r\n\r\nok"));
    }
    assert!(matches!(
        completion.try_recv(),
        Err(std::sync::mpsc::TryRecvError::Empty)
    ));
    drop(server);
    completion
        .try_recv()
        .expect("server drop must join the worker before returning");
}

fn eval_string_value(runtime: &mut JsRuntime, source: &str) -> Option<String> {
    runtime
        .eval(source)
        .unwrap()
        .as_string()
        .map(|s| s.to_std_string_escaped())
}

fn pump_zero_delay_tasks(runtime: &mut JsRuntime) {
    runtime
        .tick(0)
        .expect("zero-delay resource tasks should run");
}

#[test]
fn svg_namespace_elements_use_svg_dom_interfaces() {
    let mut runtime = JsRuntime::new().unwrap();
    assert_eq!(
        runtime
            .eval(
                r#"var d = document.implementation.createDocument('http://www.w3.org/2000/svg', 'svg', null);
                       var rect = d.createElementNS('http://www.w3.org/2000/svg', 'rect');
                       var text = d.createElementNS('http://www.w3.org/2000/svg', 'text');
                       var circle = d.createElementNS('http://www.w3.org/2000/svg', 'circle');
                       var image = d.createElementNS('http://www.w3.org/2000/svg', 'image');
                       image.setAttribute('width', '12');
                       image.setAttribute('xlink:href', 'fallback.png');
                       text.appendChild(d.createTextNode('abc'));
                       [d.documentElement instanceof SVGSVGElement,
                        rect instanceof SVGRectElement,
                        rect.constructor.name,
                        !!rect.width,
                        text instanceof SVGTextElement,
                        text instanceof SVGTextContentElement,
                        text.getNumberOfChars(),
                        circle instanceof SVGElement,
                        image instanceof SVGImageElement,
                        image instanceof SVGGraphicsElement,
                        image.width.baseVal.value,
                        image.href.baseVal,
                        Object.prototype.toString.call(image.href)].join('|')"#,
            )
            .unwrap()
            .as_string()
            .map(|s| s.to_std_string_escaped())
            .as_deref(),
        Some("true|true|SVGRectElement|true|true|true|3|true|true|true|12|fallback.png|[object SVGAnimatedString]")
    );
    assert_eq!(
        runtime
            .eval("document.createElement('rect') instanceof SVGRectElement")
            .unwrap()
            .as_boolean(),
        Some(false),
        "an HTML rect element must not receive an SVG interface"
    );
}

#[test]
fn svg_geometry_interfaces_expose_bbox_ctm_points_and_idl_shapes() {
    let mut runtime = JsRuntime::new().unwrap();
    let actual = eval_str(
        &mut runtime,
        r#"(() => {
                const ns = 'http://www.w3.org/2000/svg';
                const svg = document.createElementNS(ns, 'svg');
                svg.setAttribute('viewBox', '10 20 100 50');
                svg.setAttribute('width', '200');
                svg.setAttribute('height', '100');
                const rect = document.createElementNS(ns, 'rect');
                rect.setAttribute('x', '5');
                rect.setAttribute('y', '6');
                rect.setAttribute('width', '20');
                rect.setAttribute('height', '10');
                rect.setAttribute('transform', 'translate(3 4)');
                const circle = document.createElementNS(ns, 'circle');
                circle.setAttribute('cx', '40');
                circle.setAttribute('cy', '30');
                circle.setAttribute('r', '5');
                const path = document.createElementNS(ns, 'path');
                path.setAttribute('d', 'M 1 2 L 11 12');
                svg.appendChild(rect);
                svg.appendChild(circle);
                svg.appendChild(path);
                document.body.appendChild(svg);
                const box = rect.getBBox();
                const circleBox = circle.getBBox();
                const pathBox = path.getBBox();
                const ctm = rect.getCTM();
                const defaultStrokeBox = rect.getBBox({ stroke: true });
                rect.setAttribute('stroke', 'red');
                rect.setAttribute('stroke-width', '4');
                const strokeBox = rect.getBBox({ stroke: true });
                const matrix = new DOMMatrix([1, 2, 3, 4, 5, 6]);
                const point = svg.createSVGPoint();
                point.x = 1;
                point.y = 2;
                const transformed = point.matrixTransform(ctm);
                const widthDescriptor = Object.getOwnPropertyDescriptor(SVGRectElement.prototype, 'width');
                return [
                    rect instanceof SVGElement,
                    rect instanceof SVGGraphicsElement,
                    rect instanceof SVGGeometryElement,
                    rect instanceof SVGRectElement,
                    circle instanceof SVGCircleElement,
                    path instanceof SVGPathElement,
                    Object.prototype.toString.call(rect),
                    Object.prototype.toString.call(box),
                    Object.prototype.toString.call(point),
                    box.x, box.y, box.width, box.height,
                    circleBox.x, circleBox.y, circleBox.width, circleBox.height,
                    pathBox.x, pathBox.y, pathBox.width, pathBox.height,
                    ctm.a, ctm.d, ctm.e, ctm.f,
                    transformed.x, transformed.y,
                    matrix.m12, matrix.m21,
                    defaultStrokeBox.width, strokeBox.width,
                    svg.createSVGRect().width,
                    widthDescriptor.get !== undefined && widthDescriptor.set === undefined,
                    typeof SVGGraphicsElement.prototype.getBBox,
                    typeof SVGSVGElement.prototype.createSVGPoint
                ].join('|');
            })()"#,
    );
    assert_eq!(
        actual,
        "true|true|true|true|true|true|[object SVGRectElement]|[object SVGRect]|[object SVGPoint]|5|6|20|10|35|25|10|10|1|2|10|10|2|2|-14|-32|-12|-28|2|3|20|24|0|true|function|function"
    );
}

#[test]
fn svg_text_geometry_uses_utf16_ranges_and_nested_transforms() {
    let mut runtime = JsRuntime::new().unwrap();
    let actual = eval_str(
        &mut runtime,
        r#"(() => {
                const ns = 'http://www.w3.org/2000/svg';
                const svg = document.createElementNS(ns, 'svg');
                const text = document.createElementNS(ns, 'text');
                text.setAttribute('x', '10');
                text.setAttribute('y', '20');
                text.setAttribute('font-size', '10');
                text.appendChild(document.createTextNode('AB'));
                const span = document.createElementNS(ns, 'tspan');
                span.setAttribute('dx', '2');
                span.setAttribute('transform', 'translate(5 3)');
                span.appendChild(document.createTextNode('C'));
                text.appendChild(span);
                svg.appendChild(text);
                document.body.appendChild(svg);
                const start = text.getStartPositionOfChar(2);
                const end = text.getEndPositionOfChar(2);
                const extent = text.getExtentOfChar(2);
                const box = text.getBBox();
                const spanStart = span.getStartPositionOfChar(0);
                const spanBox = span.getBBox();
                const group = document.createElementNS(ns, 'g');
                group.setAttribute('transform', 'translate(7 4)');
                const deep = document.createElementNS(ns, 'tspan');
                deep.setAttribute('transform', 'scale(2)');
                deep.appendChild(document.createTextNode('D'));
                group.appendChild(deep);
                text.appendChild(group);
                const deepStart = deep.getStartPositionOfChar(0);
                const deepBox = deep.getBBox();
                const singular = document.createElementNS(ns, 'tspan');
                singular.setAttribute('transform', 'scale(0)');
                singular.appendChild(document.createTextNode('E'));
                text.appendChild(singular);
                let singularSafe = true;
                try { singular.getBBox(); } catch (_) { singularSafe = false; }
                const round = value => Math.round(value * 100) / 100;
                return [
                    text.getNumberOfChars(),
                    round(text.getComputedTextLength()),
                    round(text.getSubStringLength(1, 2)),
                    round(start.x), round(start.y), round(end.x), round(end.y),
                    round(extent.x), round(extent.y), round(extent.width), round(extent.height),
                    round(box.x), round(box.y), round(box.width), round(box.height),
                    start instanceof SVGPoint,
                    extent instanceof SVGRect,
                    Object.getPrototypeOf(start) === SVGPoint.prototype,
                    Object.getPrototypeOf(extent) === SVGRect.prototype,
                    Object.getOwnPropertyDescriptor(SVGRectElement.prototype, 'width').set === undefined,
                    span instanceof SVGTextContentElement,
                    span instanceof SVGTSpanElement,
                    round(spanStart.x), round(spanStart.y),
                    round(spanBox.x), round(spanBox.y),
                    round(deepStart.x), round(deepStart.y),
                    round(deepBox.x), round(deepBox.y),
                    singularSafe,
                ].join('|');
            })()"#,
    );
    assert_eq!(
        actual,
        "5|30|12|29|23|35|23|29|15|6|10|10|12|25|13|true|true|true|true|true|true|true|24|20|24|12|30|20|30|12|true"
    );
}

#[test]
fn embedded_svg_documents_are_exposed_by_iframe_and_object() {
    use crate::html::TreeBuilder;
    let (port, _port_server) = spawn_static_http_server(
        "image/svg+xml",
        r#"<svg xmlns="http://www.w3.org/2000/svg"><text>svg</text></svg>"#,
    );
    let doc = TreeBuilder::parse("<html><body></body></html>").document();
    let mut runtime =
        JsRuntime::with_document_and_url(doc, &format!("http://127.0.0.1:{port}/index.html"))
            .unwrap();
    assert_eq!(
        runtime
            .eval(
                r#"var frame = document.createElement('iframe'); frame.src = '/asset.svg';
                       var object = document.createElement('object'); object.data = '/asset.svg';
                       document.body.appendChild(frame); document.body.appendChild(object);
                       [frame.getSVGDocument() === frame.contentDocument,
                        object.getSVGDocument() === object.contentDocument,
                        frame.getSVGDocument().documentElement instanceof SVGSVGElement,
                        object.getSVGDocument().getElementsByTagName('text')[0] instanceof SVGTextElement].join('|')"#,
            )
            .unwrap()
            .as_string()
            .map(|s| s.to_std_string_escaped())
            .as_deref(),
        Some("true|true|true|true")
    );

    assert_eq!(
        runtime
            .eval("var htmlFrame = document.createElement('iframe'); htmlFrame.getSVGDocument()")
            .unwrap()
            .is_null(),
        true,
        "getSVGDocument must return null for a non-SVG document"
    );
}

#[test]
fn connected_iframe_load_supports_property_attribute_and_listener_handlers() {
    use crate::html::TreeBuilder;
    let doc = TreeBuilder::parse(
        r#"<html><body><iframe id="property"></iframe><iframe id="attribute" onload="globalThis.attributeLoads++"></iframe><iframe id="listener"></iframe></body></html>"#,
    )
    .document();
    let mut runtime = JsRuntime::with_document(doc).unwrap();
    runtime
        .eval(
            r#"globalThis.propertyLoads = 0;
                   globalThis.attributeLoads = 0;
                   globalThis.listenerLoads = 0;
                   document.getElementById('property').onload = () => propertyLoads++;
                   document.getElementById('listener').addEventListener('load', () => listenerLoads++);"#,
        )
        .unwrap();
    runtime.wire_inline_event_handlers().unwrap();

    assert_eq!(
        runtime
            .eval("propertyLoads + attributeLoads + listenerLoads")
            .unwrap()
            .as_number(),
        Some(0.0)
    );
    pump_zero_delay_tasks(&mut runtime);
    assert_eq!(
        runtime.eval("propertyLoads").unwrap().as_number(),
        Some(1.0)
    );
    assert_eq!(
        runtime.eval("attributeLoads").unwrap().as_number(),
        Some(1.0)
    );
    assert_eq!(
        runtime.eval("listenerLoads").unwrap().as_number(),
        Some(1.0)
    );
}

#[test]
