#[test]
fn document_element_scroll_reflects_the_window_scroll() {
    let mut runtime = runtime_from_html(
        r#"<html><head><style>
                 * { margin: 0; padding: 0 }
                 body { width: 600px; height: 2000px }
               </style></head><body></body></html>"#,
    );
    runtime.set_viewport(600.0, 700.0);
    let result = eval_str(
        &mut runtime,
        r#"(() => {
                const root = document.documentElement;
                const out = [];
                scrollTo(0, 300);
                out.push([root.scrollTop, document.body.scrollTop, scrollY].join(","));
                root.scrollTop = 100;
                out.push([scrollY, root.scrollTop].join(","));
                // The body is not a scroll container here, so writing to it does
                // not move the viewport.
                document.body.scrollTop = 55;
                out.push([scrollY, document.body.scrollTop].join(","));
                // scrollHeight 2000 against a 700px viewport.
                root.scrollTop = 99999;
                out.push([scrollY, root.scrollTop].join(","));
                root.scrollTo(0, 120);
                out.push(scrollY);
                root.scrollBy(0, 5);
                out.push(scrollY);
                return out.join("|");
            })()"#,
    );
    assert_eq!(result, "300,0,300|100,100|100,0|1300,1300|120|125");
}

#[test]
fn dialog_show_modal_close_moves_and_restores_focus() {
    let mut runtime = runtime_from_html(
        r#"<html><body><button id="before">before</button><dialog id="dialog"><button id="inside" tabindex="-1" autofocus>inside</button></dialog></body></html>"#,
    );
    let result = eval_str(
        &mut runtime,
        r#"(() => {
                const before = document.getElementById("before");
                const dialog = document.getElementById("dialog");
                const log = [];
                before.focus();
                dialog.addEventListener("close", event => log.push([
                  event.type, event.bubbles, event.cancelable, dialog.returnValue,
                  document.activeElement.id,
                ].join(":")));
                dialog.showModal();
                const opened = [
                  dialog instanceof HTMLDialogElement,
                  dialog.open,
                  document.activeElement.id,
                ].join(":");
                dialog.close("accepted");
                return opened + "|" + log.join("|") + "|" + dialog.open;
            })()"#,
    );
    assert_eq!(
        result,
        "true:true:inside|close:false:false:accepted:before|false"
    );
}

#[test]
fn dialog_escape_cancels_only_the_top_modal_and_honors_prevent_default() {
    let mut runtime = runtime_from_html(
        r#"<html><body><button id="before">before</button><dialog id="outer"><button id="outerButton">outer</button></dialog><dialog id="inner"><button id="innerButton">inner</button></dialog></body></html>"#,
    );
    let result = eval_str(
        &mut runtime,
        r#"(() => {
                const before = document.getElementById("before");
                const outer = document.getElementById("outer");
                const inner = document.getElementById("inner");
                const log = [];
                before.focus();
                outer.addEventListener("cancel", () => log.push("outer-cancel"));
                outer.addEventListener("close", () => log.push("outer-close"));
                inner.addEventListener("cancel", event => {
                  log.push("inner-cancel");
                  if (!inner.dataset.allowed) event.preventDefault();
                });
                inner.addEventListener("close", () => log.push("inner-close"));
                outer.showModal();
                inner.showModal();
                __omoikane_dispatch_keyboard_input("keydown", { key: "Escape", code: "Escape" });
                log.push("blocked=" + inner.open + ":" + document.activeElement.id);
                inner.dataset.allowed = "yes";
                __omoikane_dispatch_keyboard_input("keydown", { key: "Escape", code: "Escape" });
                log.push("inner=" + inner.open + ":" + document.activeElement.id);
                __omoikane_dispatch_keyboard_input("keydown", { key: "Escape", code: "Escape" });
                log.push("outer=" + outer.open + ":" + document.activeElement.id);
                return log.join("|");
            })()"#,
    );
    assert_eq!(
        result,
        concat!(
            "inner-cancel|blocked=true:innerButton|inner-cancel|inner-close|",
            "inner=false:outerButton|outer-cancel|outer-close|outer=false:before",
        )
    );
}

#[test]
fn dialog_rejects_invalid_modal_state_and_non_modal_show_is_idempotent() {
    let mut runtime = runtime_from_html("<html><body></body></html>");
    let result = eval_str(
        &mut runtime,
        r#"(() => {
                const dialog = document.createElement("dialog");
                const before = document.createElement("button");
                const outside = document.createElement("button");
                const detachedNonModal = document.createElement("dialog");
                outside.id = "outside";
                document.body.appendChild(before);
                document.body.appendChild(outside);
                const out = [dialog.returnValue, dialog.open];
                detachedNonModal.show();
                out.push(detachedNonModal.open);
                detachedNonModal.close();
                try { dialog.showModal(); } catch (error) { out.push(error.name); }
                document.body.appendChild(dialog);
                before.focus();
                dialog.show();
                dialog.show();
                out.push(dialog.open, document.activeElement === dialog);
                try { dialog.showModal(); } catch (error) { out.push(error.name); }
                outside.focus();
                dialog.close();
                dialog.close();
                out.push(dialog.open, document.activeElement.id);
                dialog.returnValue = "preserved";
                dialog.showModal();
                dialog.showModal();
                dialog.close();
                out.push(dialog.returnValue);
                return out.join(":");
            })()"#,
    );
    assert_eq!(
        result,
        ":false:true:InvalidStateError:true:true:InvalidStateError:false:outside:preserved"
    );
}

// --- iframe focus chain (issue #254) ---

/// Builds a three-level document chain: the top document, an iframe `f`
/// holding `x` and a nested iframe `g`, and `g`'s document holding `y`.
///
/// The returned prelude leaves `a`, `f`, `sub`, `x`, `g`, `sub2` and `y` on
/// `globalThis` for the test body to use.
const FOCUS_CHAIN_SETUP: &str = r#"
        globalThis.a = document.getElementById("a");
        globalThis.b = document.getElementById("b");
        globalThis.f = document.getElementById("f");
        globalThis.sub = f.contentDocument;
        globalThis.x = sub.createElement("input");
        sub.body.appendChild(x);
        globalThis.g = sub.createElement("iframe");
        sub.body.appendChild(g);
        globalThis.sub2 = g.contentDocument;
        globalThis.y = sub2.createElement("input");
        sub2.body.appendChild(y);
        globalThis.label = node => {
          if (node === a) return "a";
          if (node === b) return "b";
          if (node === f) return "f";
          if (node === g) return "g";
          if (node === x) return "x";
          if (node === y) return "y";
          if (node === document) return "doc";
          if (node === sub) return "sub";
          if (node === sub2) return "sub2";
          if (node === globalThis) return "win";
          if (node === f.contentWindow) return "subwin";
          if (node === g.contentWindow) return "sub2win";
          if (node === document.body) return "body";
          if (node === sub.body) return "subbody";
          if (node === sub2.body) return "sub2body";
          return String(node && node.nodeName);
        };
        globalThis.state = () => [
          label(document.activeElement),
          label(sub.activeElement),
          label(sub2.activeElement),
          [document.hasFocus(), sub.hasFocus(), sub2.hasFocus()].join("/"),
        ].join(" ");
        globalThis.focusLog = [];
        globalThis.watchFocus = targets => {
          for (const [node, name] of targets) {
            for (const type of ["focus", "blur", "focusin", "focusout"]) {
              node.addEventListener(type, event => focusLog.push(
                name + ":" + event.type + ":" + label(event.target) + ":" +
                (event.relatedTarget === null ? "null" : label(event.relatedTarget))
              ), true);
            }
          }
        };
    "#;

fn focus_chain_runtime() -> JsRuntime {
    let mut runtime = runtime_from_html(
        r#"<html><body><input id="a"><input id="b"><iframe id="f"></iframe></body></html>"#,
    );
    runtime.eval(FOCUS_CHAIN_SETUP).unwrap();
    runtime
}

#[test]
fn focusing_inside_an_iframe_points_each_ancestor_at_its_frame() {
    let mut runtime = focus_chain_runtime();
    let result = eval_str(
        &mut runtime,
        r#"(() => {
                const out = [state()];
                a.focus();
                out.push(state());
                // The sub-document holds the element; the parent holds the frame.
                x.focus();
                out.push(state());
                // Three levels deep, every ancestor points at the next frame.
                y.focus();
                out.push(state());
                // Leaving the chain clears the sub-documents again.
                a.focus();
                out.push(state());
                return out.join("|");
            })()"#,
    );
    assert_eq!(
        result,
        concat!(
            "body subbody sub2body true/false/false",
            "|a subbody sub2body true/false/false",
            "|f x sub2body true/true/false",
            "|f g y true/true/true",
            "|a subbody sub2body true/false/false",
        )
    );
}

/// The event sequence for a focus move that crosses documents, compared
/// entry for entry against Firefox 152 over Marionette. Listeners are
/// registered in the capture phase on every window, document and element
/// involved, so the log shows the full propagation path.
#[test]
fn crossing_documents_blurs_the_old_browsing_context_and_focuses_the_new_one() {
    let mut runtime = focus_chain_runtime();
    let result = eval_str(
        &mut runtime,
        r#"(() => {
                watchFocus([
                  [globalThis, "win"], [document, "doc"], [a, "a"],
                  [f.contentWindow, "subwin"], [sub, "sub"], [x, "x"],
                ]);
                a.focus();
                focusLog.length = 0;
                x.focus();
                return focusLog.join("|");
            })()"#,
    );
    assert_eq!(
        result,
        concat!(
            // The old element loses focus first, with no relatedTarget: the
            // new element lives in another document.
            "win:blur:a:null|doc:blur:a:null|a:blur:a:null",
            "|win:focusout:a:null|doc:focusout:a:null|a:focusout:a:null",
            // Then the browsing context it belonged to.
            "|win:blur:doc:null|doc:blur:doc:null",
            "|win:blur:win:null",
            // Then the one being entered, outermost target first.
            "|subwin:focus:sub:null|sub:focus:sub:null",
            "|subwin:focus:subwin:null",
            // And finally the new element.
            "|subwin:focus:x:null|sub:focus:x:null|x:focus:x:null",
            "|subwin:focusin:x:null|sub:focusin:x:null|x:focusin:x:null",
        )
    );
}

#[test]
fn returning_from_an_iframe_blurs_only_the_innermost_document() {
    let mut runtime = focus_chain_runtime();
    let result = eval_str(
        &mut runtime,
        r#"(() => {
                watchFocus([
                  [globalThis, "win"], [document, "doc"], [a, "a"],
                  [f.contentWindow, "subwin"], [sub, "sub"], [x, "x"],
                  [g.contentWindow, "sub2win"], [sub2, "sub2"], [y, "y"],
                ]);
                a.focus();
                x.focus();
                focusLog.length = 0;
                // Going one level deeper blurs the document being left even
                // though it stays in the chain, and leaves the top alone.
                y.focus();
                const deeper = focusLog.join("|");
                focusLog.length = 0;
                // Coming back out only blurs the innermost document.
                a.focus();
                return [deeper, focusLog.join("|")].join(";;");
            })()"#,
    );
    assert_eq!(
        result,
        concat!(
            "subwin:blur:x:null|sub:blur:x:null|x:blur:x:null",
            "|subwin:focusout:x:null|sub:focusout:x:null|x:focusout:x:null",
            "|subwin:blur:sub:null|sub:blur:sub:null",
            "|subwin:blur:subwin:null",
            "|sub2win:focus:sub2:null|sub2:focus:sub2:null",
            "|sub2win:focus:sub2win:null",
            "|sub2win:focus:y:null|sub2:focus:y:null|y:focus:y:null",
            "|sub2win:focusin:y:null|sub2:focusin:y:null|y:focusin:y:null",
            ";;",
            "sub2win:blur:y:null|sub2:blur:y:null|y:blur:y:null",
            "|sub2win:focusout:y:null|sub2:focusout:y:null|y:focusout:y:null",
            "|sub2win:blur:sub2:null|sub2:blur:sub2:null",
            "|sub2win:blur:sub2win:null",
            "|win:focus:doc:null|doc:focus:doc:null",
            "|win:focus:win:null",
            "|win:focus:a:null|doc:focus:a:null|a:focus:a:null",
            "|win:focusin:a:null|doc:focusin:a:null|a:focusin:a:null",
        )
    );
}

#[test]
fn same_document_focus_moves_do_not_touch_the_browsing_context() {
    let mut runtime = focus_chain_runtime();
    let result = eval_str(
        &mut runtime,
        r#"(() => {
                watchFocus([[globalThis, "win"], [document, "doc"], [a, "a"], [b, "b"]]);
                a.focus();
                focusLog.length = 0;
                b.focus();
                // No document- or window-targeted event, and relatedTarget is
                // exposed because both elements share a document.
                return focusLog.join("|");
            })()"#,
    );
    assert_eq!(
        result,
        concat!(
            "win:blur:a:b|doc:blur:a:b|a:blur:a:b",
            "|win:focusout:a:b|doc:focusout:a:b|a:focusout:a:b",
            "|win:focus:b:a|doc:focus:b:a|b:focus:b:a",
            "|win:focusin:b:a|doc:focusin:b:a|b:focusin:b:a",
        )
    );
}

#[test]
fn blurring_inside_an_iframe_keeps_the_frame_focused() {
    let mut runtime = focus_chain_runtime();
    let result = eval_str(
        &mut runtime,
        r#"(() => {
                x.focus();
                const before = state();
                // The unfocusing steps hand focus to the sub-document's viewport,
                // so the frame stays the parent's active element and the
                // sub-document keeps system focus.
                x.blur();
                return [before, state()].join("|");
            })()"#,
    );
    assert_eq!(
        result,
        "f x sub2body true/true/false|f subbody sub2body true/true/false"
    );
}

#[test]
fn removing_a_focused_iframe_hands_focus_back_to_the_top_document() {
    let mut runtime = focus_chain_runtime();
    let result = eval_str(
        &mut runtime,
        r#"(() => {
                y.focus();
                const before = state();
                f.remove();
                // The frame and its documents are gone, so the top-level
                // document is focused again with nothing focused inside it.
                return [
                  before,
                  label(document.activeElement),
                  document.hasFocus(),
                ].join("|");
            })()"#,
    );
    assert_eq!(result, "f g y true/true/true|body|true");
}

/// Every handler must see the state its own event announces. Snapshots taken
/// inside each handler of a cross-document move, compared against Firefox
/// 152: focus has left the old context by the time its `blur` pair runs, and
/// the new chain is already installed when its `focus` pair runs, while the
/// element itself is only focused for the element's own event.
#[test]
fn browsing_context_focus_events_observe_the_state_they_announce() {
    let mut runtime = focus_chain_runtime();
    let result = eval_str(
        &mut runtime,
        r#"(() => {
                const snapshots = [];
                const snap = tag => snapshots.push([
                  tag,
                  document.hasFocus(),
                  sub.hasFocus(),
                  label(document.activeElement),
                  label(sub.activeElement),
                ].join(":"));
                a.focus();
                a.addEventListener("blur", () => snap("element-blur"), true);
                document.addEventListener("blur", event => {
                  if (event.target === document) snap("doc-blur");
                }, true);
                globalThis.addEventListener("blur", event => {
                  if (event.target === globalThis) snap("win-blur");
                }, true);
                sub.addEventListener("focus", event => {
                  if (event.target === sub) snap("sub-focus");
                }, true);
                f.contentWindow.addEventListener("focus", event => {
                  if (event.target === f.contentWindow) snap("subwin-focus");
                }, true);
                x.addEventListener("focus", () => snap("element-focus"), true);

                x.focus();
                snap("after");
                return snapshots.join("|");
            })()"#,
    );
    assert_eq!(
        result,
        concat!(
            // The old context still holds focus while its element blurs.
            "element-blur:true:false:body:subbody",
            // In transit: no document reports focus.
            "|doc-blur:false:false:body:subbody",
            "|win-blur:false:false:body:subbody",
            // The chain is in place — the parent already points at the frame —
            // before the entered context is announced.
            "|sub-focus:true:true:f:subbody",
            "|subwin-focus:true:true:f:subbody",
            // The element is focused only for its own event.
            "|element-focus:true:true:f:x",
            "|after:true:true:f:x",
        )
    );
}

#[test]
fn message_ports_deliver_fifo_tasks_with_microtask_checkpoints() {
    let mut runtime = JsRuntime::new().unwrap();
    assert_eq!(
        eval_str(
            &mut runtime,
            r#"(() => { globalThis.log = [];
                   globalThis.channel = new MessageChannel();
                   channel.port2.onmessage = event => {
                     const label = typeof event.data === "object" ? event.data.value : event.data;
                     log.push("message:" + label + ":" + event.origin + ":" +
                       (event.source === null) + ":" + event.ports.length);
                     Promise.resolve().then(() => log.push("micro:" + label));
                   };
                   channel.port1.postMessage(1);
                   channel.port1.postMessage(2);
                   const payload = { value: 3 };
                   channel.port1.postMessage(payload);
                   payload.value = 9;
                   return log.join("|"); })()"#,
        ),
        ""
    );
    assert_eq!(
        eval_str(
            &mut runtime,
            "channel.port1 !== channel.port2 && channel.port1 instanceof MessagePort && channel.port2 instanceof MessagePort",
        ),
        "true"
    );
    runtime.run_until_idle().unwrap();
    assert_eq!(
        eval_str(&mut runtime, "log.join('|')"),
        "message:1::true:0|micro:1|message:2::true:0|micro:2|message:3::true:0|micro:3"
    );
}

#[test]
fn message_port_start_close_and_listener_errors_follow_task_semantics() {
    let mut runtime = JsRuntime::new().unwrap();
    eval_str(
        &mut runtime,
        r#"(() => { globalThis.log = []; globalThis.listenerErrors = [];
               window.addEventListener('error', event => listenerErrors.push(event.message));
               globalThis.channel = new MessageChannel();
               channel.port2.addEventListener("message", event => {
                 log.push(event.data);
                 if (event.data === "first") throw new Error("listener failed");
               });
               channel.port1.postMessage("first");
               channel.port1.postMessage("second");
               channel.port2.start();
               channel.port1.postMessage("third"); return ""; })()"#,
    );
    runtime.run_until_idle().unwrap();
    assert_eq!(
        eval_str(&mut runtime, "log.join('|')"),
        "first|second|third"
    );
    assert_eq!(runtime.take_task_errors().len(), 0);
    assert_eq!(
        eval_str(
            &mut runtime,
            "listenerErrors.length === 1 && listenerErrors[0].includes('listener failed')"
        ),
        "true"
    );
    eval_str(
        &mut runtime,
        "(() => { channel.port2.close(); channel.port1.postMessage('third'); })()",
    );
    runtime.run_until_idle().unwrap();
    assert_eq!(
        eval_str(&mut runtime, "log.join('|')"),
        "first|second|third"
    );
}

#[test]
fn structured_clone_snapshots_cycles_builtins_and_rejects_unsupported_values() {
    let mut runtime = JsRuntime::new().unwrap();
    let result = eval_str(
        &mut runtime,
        r#"(() => {
              const source = { nested: { value: 1 } };
              source.self = source;
              source.date = new Date(1234);
              source.regexp = /ab/gi;
              source.map = new Map([["key", { value: 2 }]]);
              source.set = new Set([3]);
              source.bytes = new Uint8Array([4, 5]);
              const clone = structuredClone(source);
              source.nested.value = 9;
              source.map.get("key").value = 8;
              source.bytes[0] = 7;
              const sparse = structuredClone(new Array(3));
              let errors = [];
              for (const value of [() => {}, Symbol("x"), document.body]) {
                try { structuredClone(value); } catch (error) { errors.push(error.name); }
              }
              return [
                clone !== source,
                clone.self === clone,
                clone.nested.value,
                clone.date.getTime(),
                clone.regexp.source + clone.regexp.flags,
                clone.map.get("key").value,
                clone.set.has(3),
                Array.from(clone.bytes).join(","),
                sparse.length + ":" + Object.keys(sparse).length,
                errors.join(","),
              ].join("|");
            })()"#,
    );
    assert_eq!(
        result,
        "true|true|1|1234|abgi|2|true|4,5|3:0|DataCloneError,DataCloneError,DataCloneError"
    );
}

#[test]
fn run_timers_caps_self_scheduling_posted_messages() {
    let mut runtime = JsRuntime::new().unwrap();
    eval_str(
        &mut runtime,
        r#"(() => {
              globalThis.messageCount = 0;
              globalThis.channel = new MessageChannel();
              channel.port2.onmessage = () => {
                messageCount++;
                channel.port1.postMessage(null);
              };
              channel.port1.postMessage(null);
              setTimeout(() => {}, 0);
            })()"#,
    );
    assert_eq!(runtime.run_timers(100, 1, 5), 1);
    assert_eq!(eval_str(&mut runtime, "messageCount"), "4");
}

#[test]
fn broadcast_channel_delivers_same_origin_messages_asynchronously() {
    let mut sender =
        JsRuntime::with_document_and_url(default_document(), "https://example.test/sender")
            .unwrap();
    let mut receiver =
        JsRuntime::with_document_and_url(default_document(), "https://example.test/receiver")
            .unwrap();
    let mut other_origin =
        JsRuntime::with_document_and_url(default_document(), "https://other.test/receiver")
            .unwrap();

    eval_str(
        &mut sender,
        "(() => { globalThis.events = []; globalThis.channel = new BroadcastChannel('events'); channel.onmessage = event => events.push(event.data); })()",
    );
    eval_str(
        &mut receiver,
        "(() => { globalThis.events = []; globalThis.channel = new BroadcastChannel('events'); channel.onmessage = event => events.push({ value: event.data.value, origin: event.origin, proto: Object.getPrototypeOf(event.data) === Object.prototype }); })()",
    );
    eval_str(
        &mut other_origin,
        "(() => { globalThis.events = []; globalThis.channel = new BroadcastChannel('events'); channel.onmessage = event => events.push(event.data); })()",
    );

    eval_str(
        &mut sender,
        "(() => { channel.postMessage({ value: 7 }); })()",
    );
    assert_eq!(eval_str(&mut sender, "events.length"), "0");
    assert_eq!(eval_str(&mut receiver, "events.length"), "0");

    receiver.run_until_idle().unwrap();
    other_origin.run_until_idle().unwrap();
    assert_eq!(eval_str(&mut sender, "events.length"), "0");
    assert_eq!(
        eval_str(
            &mut receiver,
            "events[0].value + '|' + events[0].origin + '|' + events[0].proto"
        ),
        "7|https://example.test|true"
    );
    assert_eq!(eval_str(&mut other_origin, "events.length"), "0");
}

#[test]
fn broadcast_channel_close_cleans_registry_and_clone_errors_are_synchronous() {
    let mut sender =
        JsRuntime::with_document_and_url(default_document(), "http://example.test/sender").unwrap();
    let mut receiver =
        JsRuntime::with_document_and_url(default_document(), "http://example.test/receiver")
            .unwrap();

    eval_str(
        &mut sender,
        "(() => { globalThis.channel = new BroadcastChannel('close'); globalThis.error = ''; try { channel.postMessage(() => {}); } catch (event) { error = event.name; } })()",
    );
    assert_eq!(eval_str(&mut sender, "error"), "DataCloneError");

    eval_str(
        &mut receiver,
        "(() => { globalThis.count = 0; globalThis.errorCount = 0; globalThis.channel = new BroadcastChannel('close'); channel.onmessage = () => count++; channel.onmessageerror = () => errorCount++; channel.close(); })()",
    );
    eval_str(&mut sender, "(() => { channel.postMessage('ignored'); })()");
    receiver.run_until_idle().unwrap();
    assert_eq!(eval_str(&mut receiver, "count + ':' + errorCount"), "0:0");

    eval_str(
        &mut receiver,
        "(() => { globalThis.channel = new BroadcastChannel('close'); channel.onmessage = event => { globalThis.value = event.data; }; })()",
    );
    eval_str(
        &mut sender,
        "(() => { channel.postMessage({ nested: { value: 3 } }); })()",
    );
    receiver.run_until_idle().unwrap();
    assert_eq!(eval_str(&mut receiver, "value.nested.value"), "3");
    eval_str(&mut receiver, "(() => { channel.close(); })()");
    let result = sender.eval("channel.postMessage('after-close')");
    assert!(result.is_ok());
}

#[test]
fn broadcast_channel_decode_failure_dispatches_messageerror_only() {
    let mut runtime =
        JsRuntime::with_document_and_url(default_document(), "https://example.test/broadcast")
            .unwrap();
    eval_str(
        &mut runtime,
        r#"(() => { globalThis.messages = 0; globalThis.errors = 0;
               globalThis.senderChannel = new BroadcastChannel('decode');
               globalThis.receiverChannel = new BroadcastChannel('decode');
               receiverChannel.onmessage = () => messages++;
               receiverChannel.onmessageerror = () => errors++;
               })()"#,
    );
    // Inject an invalid clone wire through the private host callback from
    // Rust, without making the callback callable by page scripts.
    let channel_id = runtime.eval("senderChannel._id").unwrap();
    {
        let _host = activate_host_state(Rc::clone(&runtime.host_state));
        broadcast_channel_post_native(
            &JsValue::undefined(),
            &[channel_id, JsValue::from(js_string!("{}"))],
            &mut runtime.context,
        )
        .unwrap();
    }
    runtime.run_until_idle().unwrap();
    assert_eq!(eval_str(&mut runtime, "messages + ':' + errors"), "0:1");
}

#[test]
fn cache_storage_snapshots_match_options_and_delivers_on_networking_tasks() {
    let storage = StorageManager::new();
    let first_session = storage.create_session();
    let second_session = storage.create_session();
    let mut runtime = JsRuntime::with_document_url_and_storage(
        default_document(),
        "https://cache.example.test/page",
        storage.clone(),
        first_session,
    )
    .unwrap();

    eval_str(
        &mut runtime,
        r#"(() => {
              globalThis.cacheProbe = { events: [], body: '', ignoredSearch: '', varied: true, ignoredVary: '' };
              caches.open('v1').then(cache => {
                cacheProbe.events.push('opened');
                const request = new Request('/asset?a=1', { headers: { Accept: 'text/plain' } });
                const response = new Response('snapshot', { headers: { Vary: 'Accept', 'X-Cache': 'yes' } });
                return cache.put(request, response).then(() => {
                  cacheProbe.events.push('put');
                  return Promise.all([
                    cache.match(new Request('/asset?a=1', { headers: { Accept: 'text/plain' } })).then(value => value.text()),
                    cache.match(new Request('/asset?a=2', { headers: { Accept: 'text/plain' } }), { ignoreSearch: true }).then(value => value.text()),
                    cache.match(new Request('/asset?a=1', { headers: { Accept: 'application/json' } })),
                    cache.match('/asset?a=1', { ignoreVary: true }).then(value => value.text()),
                    cache.match(new Request('/asset?a=1', { headers: { Accept: 'text/plain' } })).then(value => value.text()),
                  ]);
                });
              }).then(values => {
                cacheProbe.events.push('matched');
                cacheProbe.body = values[0];
                cacheProbe.ignoredSearch = values[1];
                cacheProbe.varied = values[2] === undefined;
                cacheProbe.ignoredVary = values[3];
                cacheProbe.secondRead = values[4];
              });
              globalThis.cacheRejected = { method: false, opaque: false, vary: false };
              caches.open('v1').then(cache => {
                cache.put(new Request('/post', { method: 'POST' }), new Response('bad'))
                  .then(() => {}, error => { cacheRejected.method = error instanceof TypeError; });
                const opaque = new Response('opaque');
                opaque.type = 'opaque';
                cache.put('/opaque', opaque)
                  .then(() => {}, error => { cacheRejected.opaque = error instanceof TypeError; });
                cache.put('/vary-star', new Response('bad', { headers: { Vary: '*' } }))
                  .then(() => {}, error => { cacheRejected.vary = error instanceof TypeError; });
              });
            })()"#,
    );
    assert_eq!(eval_str(&mut runtime, "cacheProbe.events.length"), "0");
    runtime.run_until_idle().unwrap();
    assert_eq!(
        eval_str(&mut runtime, "cacheProbe.events.join(',')"),
        "opened,put,matched"
    );
    assert_eq!(eval_str(&mut runtime, "cacheProbe.body"), "snapshot");
    assert_eq!(
        eval_str(&mut runtime, "cacheProbe.ignoredSearch"),
        "snapshot"
    );
    assert_eq!(
        eval_str(
            &mut runtime,
            "cacheProbe.varied + ':' + cacheProbe.ignoredVary"
        ),
        "true:snapshot"
    );
    assert_eq!(eval_str(&mut runtime, "cacheProbe.secondRead"), "snapshot");
    assert_eq!(
        eval_str(
            &mut runtime,
            "cacheRejected.method + ':' + cacheRejected.opaque + ':' + cacheRejected.vary"
        ),
        "true:true:true"
    );
    eval_str(
        &mut runtime,
        "(() => { globalThis.cacheHas = undefined; caches.has('v1').then(value => { cacheHas = value; }); })()",
    );
    assert_eq!(eval_str(&mut runtime, "cacheHas === undefined"), "true");
    runtime.run_until_idle().unwrap();
    assert_eq!(eval_str(&mut runtime, "cacheHas"), "true");
    eval_str(
        &mut runtime,
        "(() => { globalThis.cacheNames = []; caches.keys().then(names => { cacheNames = names; }); })()",
    );
    assert_eq!(eval_str(&mut runtime, "cacheNames.length"), "0");
    runtime.run_until_idle().unwrap();
    assert_eq!(eval_str(&mut runtime, "cacheNames.join(',')"), "v1");

    // StorageManager is shared by independently created realms: the
    // origin namespace is visible in the second runtime, while another
    // origin receives an empty CacheStorage namespace.
    let mut same_origin = JsRuntime::with_document_url_and_storage(
        default_document(),
        "https://cache.example.test/other",
        storage.clone(),
        second_session,
    )
    .unwrap();
    eval_str(
        &mut same_origin,
        "(() => { globalThis.cacheNames = []; caches.keys().then(names => { cacheNames = names; }); })()",
    );
    assert_eq!(eval_str(&mut same_origin, "cacheNames.length"), "0");
    same_origin.run_until_idle().unwrap();
    assert_eq!(eval_str(&mut same_origin, "cacheNames.join(',')"), "v1");

    let mut other_origin = JsRuntime::with_document_url_and_storage(
        default_document(),
        "https://other-cache.example.test/",
        storage,
        second_session,
    )
    .unwrap();
    eval_str(
        &mut other_origin,
        "(() => { globalThis.cacheNames = []; caches.keys().then(names => { cacheNames = names; }); })()",
    );
    other_origin.run_until_idle().unwrap();
    assert_eq!(eval_str(&mut other_origin, "cacheNames.length"), "0");

    let mut opaque_origin = JsRuntime::with_document_url_and_storage(
        default_document(),
        "data:text/html,<p>opaque</p>",
        StorageManager::new(),
        1,
    )
    .unwrap();
    eval_str(
        &mut opaque_origin,
        "(() => { globalThis.cacheError = ''; caches.open('opaque').then(() => { cacheError = 'resolved'; }, error => { cacheError = error.name; }); })()",
    );
    assert_eq!(eval_str(&mut opaque_origin, "cacheError"), "");
    opaque_origin.run_until_idle().unwrap();
    assert_eq!(eval_str(&mut opaque_origin, "cacheError"), "SecurityError");
}
